import fs from 'node:fs';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';

export const STATE_VERSION = 1;

export class DeliverError extends Error {
  constructor(message, code = 70, details = undefined) {
    super(message);
    this.name = 'DeliverError';
    this.code = code;
    this.details = details;
  }
}

export const sha256 = (value) => createHash('sha256').update(value).digest('hex');

export function canonical(value) {
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

export function readJsonFile(file, label = file) {
  let raw;
  try {
    if (fs.statSync(file).size > 8 * 1024 * 1024) throw new Error('file exceeds 8 MiB');
    raw = fs.readFileSync(file, 'utf8');
  }
  catch (error) { throw new DeliverError(`cannot read ${label}: ${error.message}`, 66); }
  try { return JSON.parse(raw); }
  catch (error) { throw new DeliverError(`invalid JSON in ${label}: ${error.message}`, 66); }
}

const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isStringArray = (value) => Array.isArray(value) && value.every((item) => typeof item === 'string');
const safeBranch = (value) => typeof value === 'string' && value && value.length <= 512 && value !== '@'
  && !value.startsWith('-') && !value.startsWith('/') && !value.endsWith('/') && !value.endsWith('.')
  && !value.includes('..') && !value.includes('//') && !value.includes('@{')
  && !/[\x00-\x20\x7f~^:?*[\\\]]/.test(value)
  && value.split('/').every((part) => part && !part.startsWith('.') && !part.endsWith('.lock'));
const safeRef = (value) => typeof value === 'string' && value.startsWith('refs/heads/') && safeBranch(value.slice('refs/heads/'.length));
const safeRelativePath = (value) => typeof value === 'string' && value && !path.isAbsolute(value)
  && !/[\x00-\x1f\x7f]/.test(value) && !value.split(/[\\/]/).some((part) => !part || part === '.' || part === '..')
  && !/^(?:\.git|\.deliver)(?:[\\/]|$)/.test(value);
const oid = (value) => typeof value === 'string' && /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(value);
const digest = (value) => typeof value === 'string' && /^[0-9a-f]{64}$/.test(value);

function validNestedAnchor(anchor) {
  if (!isObject(anchor) || !['head', 'tree', 'index_tree', 'index_flags', 'protected_hash']
    .every((key) => typeof anchor[key] === 'string')
    || !oid(anchor.head) || !oid(anchor.tree) || !oid(anchor.index_tree)
    || !digest(anchor.index_flags) || !digest(anchor.protected_hash)
    || (anchor.metadata_version !== undefined && anchor.metadata_version !== 'protected-v2')) return false;
  if (anchor.submodules === undefined) return true;
  return isObject(anchor.submodules) && Object.entries(anchor.submodules)
    .every(([rel, nested]) => safeRelativePath(rel) && validNestedAnchor(nested));
}

export function archiveEvidence(state, reason, details = {}, archivedAt = new Date().toISOString()) {
  if (!isObject(state) || typeof reason !== 'string' || !reason.trim() || !isObject(details)
    || typeof archivedAt !== 'string' || Number.isNaN(Date.parse(archivedAt))) {
    throw new DeliverError('cannot archive evidence without a state, reason and detail object', 66);
  }
  const hasEvidence = state.gates.length > 0 || state.review !== null || state.verification !== null;
  if (hasEvidence) {
    if (state.evidence_history === undefined) state.evidence_history = [];
    state.evidence_history.push({
      at: archivedAt,
      reason,
      details: structuredClone(details),
      gates: structuredClone(state.gates),
      review: structuredClone(state.review),
      verification: structuredClone(state.verification),
    });
  }
  state.gates = [];
  state.review = null;
  state.verification = null;
}

export function validateTaskPacket(packet) {
  if (!isObject(packet)) throw new DeliverError('task packet must be a JSON object', 66);
  const unknown = Object.keys(packet).filter((key) => !['id', 'objective', 'acceptance', 'read_paths', 'touches', 'commands', 'specs'].includes(key));
  if (unknown.length) throw new DeliverError(`unsupported task fields: ${unknown.join(', ')}`, 66);
  for (const key of ['id', 'objective']) {
    if (typeof packet[key] !== 'string' || packet[key].trim() === '') throw new DeliverError(`task packet ${key} must be a non-empty string`, 66);
  }
  if (!Array.isArray(packet.acceptance) || packet.acceptance.length === 0) {
    throw new DeliverError('task packet acceptance must be a non-empty array', 66);
  }
  const acceptance = packet.acceptance.map((item, index) => {
    if (!isObject(item) || typeof item.id !== 'string' || item.id.trim() === '' || typeof item.text !== 'string' || item.text.trim() === '') {
      throw new DeliverError(`task packet acceptance[${index}] must contain non-empty id and text strings`, 66);
    }
    return { id: item.id, text: item.text };
  });
  if (new Set(acceptance.map((item) => item.id)).size !== acceptance.length) throw new DeliverError('task packet acceptance ids must be unique', 66);
  if (!isStringArray(packet.read_paths) || !isStringArray(packet.touches)) {
    throw new DeliverError('task packet read_paths and touches must be string arrays', 66);
  }
  if (packet.touches.length === 0) throw new DeliverError('task packet touches must not be empty', 66);
  if (!isObject(packet.commands)) throw new DeliverError('task packet commands must be an object; use {} to record N/A', 66);
  const commands = Object.create(null);
  for (const [name, command] of Object.entries(packet.commands)) {
    if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(name) || typeof command !== 'string' || command.trim() === '') {
      throw new DeliverError('task packet command names and values must be non-empty safe strings', 66);
    }
    commands[name] = command;
  }
  if (packet.specs !== undefined && !isStringArray(packet.specs)) throw new DeliverError('task packet specs must be an array of strings', 66);
  return {
    id: packet.id,
    objective: packet.objective,
    acceptance,
    read_paths: [...packet.read_paths],
    touches: [...packet.touches],
    commands,
    specs: [...(packet.specs || [])],
  };
}

export function validateRunState(state) {
  const fail = (message) => { throw new DeliverError(`invalid run state: ${message}`, 66); };
  if (!isObject(state)) fail('root must be an object');
  if (state.schema_version !== STATE_VERSION) fail(`schema_version must be ${STATE_VERSION}`);
  if (typeof state.run_id !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(state.run_id)) fail('bad run_id');
  if (!['quick', 'managed', 'governed'].includes(state.mode)) fail('bad mode');
  if (!Number.isSafeInteger(state.revision) || state.revision < 0) fail('bad revision');
  if (typeof state.project_root !== 'string' || !path.isAbsolute(state.project_root)) fail('bad project_root');
  if (!isObject(state.plan) || (state.plan.path !== null && typeof state.plan.path !== 'string') || typeof state.plan.hash !== 'string') fail('bad plan');
  if (state.approval !== null && (!isObject(state.approval) || typeof state.approval.approver !== 'string' || typeof state.approval.plan_hash !== 'string')) fail('bad approval');
  if (!['initialized', 'starting', 'active', 'finished'].includes(state.phase)) fail('bad phase');
  if (!isObject(state.counters) || !['retries', 'fixes', 'corrections'].every((key) => Number.isSafeInteger(state.counters[key]) && state.counters[key] >= 0)) fail('bad counters');
  if (!Array.isArray(state.events) || !Array.isArray(state.gates) || !Array.isArray(state.checkpoints)) fail('bad collections');
  if (state.task !== null) {
    if (!isObject(state.task) || typeof state.task.builder !== 'string' || !isObject(state.task.packet)) fail('bad task');
    validateTaskPacket(state.task.packet);
  }
  if (state.baseline !== null) {
    if (!isObject(state.baseline) || !isObject(state.baseline.snapshot) || !isObject(state.baseline.snapshot.entries)
      || typeof state.baseline.snapshot.git_meta !== 'string' || typeof state.baseline.snapshot.hash !== 'string'
      || !isStringArray(state.baseline.dirty_paths)) fail('bad baseline');
    const expectedHash = sha256(canonical({ entries: state.baseline.snapshot.entries, git_meta: state.baseline.snapshot.git_meta }));
    if (state.baseline.snapshot.hash !== expectedHash) fail('baseline snapshot hash does not match its content');
  }
  if (state.pm_binding !== undefined && state.pm_binding !== null) {
    const binding = state.pm_binding;
    const safeActor = (value) => typeof value === 'string' && /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?-[a-f0-9]{12}$/.test(value);
    const safeStoryPath = (value) => typeof value === 'string' && /^docs\/stories\/S\d+-\d+-[^/\\]+\.md$/.test(value);
    if (!isObject(binding)) fail('bad PM binding');
    if (binding.format === 'current') {
      if (!['actor', 'story', 'story_path', 'contract_hash', 'execution_hash', 'plan_digest', 'branch', 'builder', 'integration_branch']
        .every((key) => typeof binding[key] === 'string')) fail('bad current PM binding');
      if (!safeActor(binding.actor) || !/^S\d+-\d+$/.test(binding.story) || !safeStoryPath(binding.story_path)
        || !/^[0-9a-f]{64}$/.test(binding.contract_hash) || !/^[0-9a-f]{64}$/.test(binding.execution_hash)
        || !/^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(binding.plan_digest)
        || !safeBranch(binding.branch) || !safeBranch(binding.integration_branch)
        || !['codex-builder', 'expert-builder'].includes(binding.builder)) fail('unsafe current PM binding');
    } else {
      if (binding.format !== undefined && binding.format !== 'legacy') fail('unsupported PM binding format');
      if (!['actor', 'story', 'story_path', 'story_hash', 'integration_branch', 'actor_path'].every((key) => typeof binding[key] === 'string')) fail('bad legacy PM binding');
      if (!safeActor(binding.actor) || binding.actor_path !== `pm/actors/${binding.actor}.json`
        || !binding.story_path.startsWith('docs/stories/') || binding.story_path.split(/[\\/]/).includes('..')) fail('unsafe legacy PM binding');
    }
  }
  if (state.git_anchor !== undefined && state.git_anchor !== null) {
    const anchor = state.git_anchor;
    if (!isObject(anchor) || !['head', 'ref', 'tree', 'index_tree', 'index_flags', 'protected_hash']
      .every((key) => typeof anchor[key] === 'string')) fail('bad git anchor');
    if (!oid(anchor.head) || !oid(anchor.tree) || !oid(anchor.index_tree)
      || !digest(anchor.index_flags) || !digest(anchor.protected_hash)
      || !safeRef(anchor.ref)
      || (anchor.metadata_version !== undefined && anchor.metadata_version !== 'protected-v2')
      || (anchor.submodules !== undefined && (!isObject(anchor.submodules) || !Object.entries(anchor.submodules)
        .every(([rel, nested]) => safeRelativePath(rel) && validNestedAnchor(nested))))) fail('unsafe git anchor');
  }
  if (state.baseline_metadata_version !== undefined
    && (state.baseline_metadata_version !== 'legacy-v1' || !state.git_anchor)) fail('bad baseline metadata compatibility marker');
  if (state.execution_audit !== undefined && state.execution_audit !== null) {
    const audit = state.execution_audit;
    if (!isObject(audit) || typeof audit.story_path !== 'string' || typeof audit.contract_hash !== 'string'
      || !(audit.original_entry === null || /^file:(?:644|755):[0-9a-f]{64}$/.test(audit.original_entry))
      || !/^file:(?:644|755):[0-9a-f]{64}$/.test(audit.current_entry) || !Array.isArray(audit.transitions)
      || !/^docs\/stories\/S\d+-\d+-[^/\\]+\.md$/.test(audit.story_path)
      || !/^[0-9a-f]{64}$/.test(audit.contract_hash)) fail('bad Execution audit');
    for (const item of audit.transitions) {
      if (!isObject(item) || !['from', 'to', 'before_hash', 'after_hash', 'at'].every((key) => typeof item[key] === 'string')
        || !['claimed', 'building', 'built', 'in-review', 'blocked'].includes(item.from)
        || !['claimed', 'building', 'built', 'in-review', 'blocked'].includes(item.to)
        || !/^[0-9a-f]{64}$/.test(item.before_hash) || !/^[0-9a-f]{64}$/.test(item.after_hash)
        || !(item.reason === null || typeof item.reason === 'string')
        || (item.attempt !== null && item.attempt !== undefined && !['fix', 'retry'].includes(item.attempt))) fail('bad Execution transition receipt');
    }
  }
  if (state.commit_adoption !== undefined && state.commit_adoption !== null) {
    const adoption = state.commit_adoption;
    if (!isObject(adoption) || !Array.isArray(adoption.history) || !(adoption.pending === null || isObject(adoption.pending))) fail('bad commit adoption state');
    if (adoption.pending) {
      const pending = adoption.pending;
      if (!['token', 'parent', 'ref', 'expected_tree', 'expected_index_flags', 'content_hash', 'protected_hash', 'prepared_at'].every((key) => typeof pending[key] === 'string')
        || !Array.isArray(pending.paths) || !isStringArray(pending.paths) || !pending.paths.every(safeRelativePath)
        || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(pending.token)
        || ![pending.parent, pending.expected_tree].every((value) => /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(value))
        || ![pending.expected_index_flags, pending.content_hash, pending.protected_hash].every(digest)
        || !safeRef(pending.ref)) fail('bad pending commit adoption');
    }
    for (const item of adoption.history) {
      if (!isObject(item) || typeof item.commit !== 'string' || typeof item.parent !== 'string'
        || !/^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(item.commit)
        || !/^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(item.parent)
        || typeof item.tree !== 'string' || !/^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(item.tree)
        || !safeRef(item.ref) || !isStringArray(item.paths) || !item.paths.every(safeRelativePath)
        || !['claimed', 'building', 'built', 'in-review'].includes(item.execution_status)
        || typeof item.execution_hash !== 'string' || !/^[0-9a-f]{64}$/.test(item.execution_hash)
        || typeof item.adopted_at !== 'string') fail('bad commit adoption receipt');
    }
  }
  if (state.evidence_history !== undefined) {
    if (!Array.isArray(state.evidence_history)) fail('bad evidence history');
    for (const item of state.evidence_history) {
      if (!isObject(item) || typeof item.at !== 'string' || typeof item.reason !== 'string' || !item.reason.trim()
        || !isObject(item.details)
        || !Array.isArray(item.gates) || !(item.review === null || isObject(item.review))
        || !(item.verification === null || isObject(item.verification))) fail('bad evidence history item');
    }
  }
  if (state.completion_snapshot !== undefined) {
    const snap = state.completion_snapshot;
    if (!isObject(snap) || !isObject(snap.entries) || typeof snap.git_meta !== 'string'
      || snap.hash !== sha256(canonical({ entries: snap.entries, git_meta: snap.git_meta }))
      || state.phase !== 'finished' || snap.hash !== state.review?.snapshot_hash || snap.hash !== state.verification?.snapshot_hash) fail('bad completion snapshot');
  }
  for (const gate of state.gates) {
    if (!isObject(gate) || gate.provenance !== 'deliver-runtime-executed-v1' || typeof gate.name !== 'string'
      || typeof gate.command !== 'string' || !['PASS', 'FAIL'].includes(gate.status)
      || typeof gate.snapshot_hash !== 'string' || typeof gate.environment_hash !== 'string'
      || typeof gate.environment_additions_hash !== 'string') fail('bad gate receipt');
  }
  if (state.review !== null && (!isObject(state.review) || !['PASS', 'FAIL'].includes(state.review.status)
    || typeof state.review.builder !== 'string' || typeof state.review.reviewer !== 'string'
    || !Array.isArray(state.review.findings) || typeof state.review.snapshot_hash !== 'string')) fail('bad review');
  if (state.review?.panel !== undefined) {
    const panel = state.review.panel;
    if (!isObject(panel) || panel.snapshot_hash !== state.review.snapshot_hash || !Array.isArray(panel.members)
      || !panel.members.length || panel.members.length > 16) fail('bad review panel');
    for (const member of panel.members) {
      if (!isObject(member) || typeof member.lens !== 'string' || !/^[a-z][a-z0-9-]{0,63}$/.test(member.lens)
        || typeof member.reviewer !== 'string' || !['PASS', 'CONCERNS', 'FAIL'].includes(member.verdict)
        || member.snapshot_hash !== panel.snapshot_hash || !Array.isArray(member.findings)) fail('bad review panel member');
      for (const finding of member.findings) {
        if (!isObject(finding) || !['block', 'major', 'minor'].includes(finding.severity)
          || typeof finding.message !== 'string' || !finding.message.trim() || typeof finding.resolved !== 'boolean') fail('bad review panel finding');
      }
      if (member.verdict === 'PASS' && member.findings.some((finding) => !finding.resolved && finding.severity !== 'minor')) fail('invalid PASS panel member');
      if (member.verdict === 'CONCERNS' && !member.findings.some((finding) => !finding.resolved)) fail('invalid CONCERNS panel member');
    }
    if (new Set(panel.members.map((member) => member.lens)).size !== panel.members.length) fail('duplicate review panel lens');
    const derivedFindings = panel.members.flatMap((member) => member.findings
      .map((finding) => ({ ...finding, lens: member.lens, reviewer: member.reviewer })));
    const derivedStatus = panel.members.some((member) => member.verdict === 'FAIL')
      || derivedFindings.some((finding) => !finding.resolved && finding.severity !== 'minor') ? 'FAIL' : 'PASS';
    if (state.review.status !== derivedStatus || canonical(state.review.findings) !== canonical(derivedFindings)) fail('review panel aggregate is inconsistent');
  }
  if (state.verification !== null && (!isObject(state.verification) || typeof state.verification.verifier !== 'string'
    || !Array.isArray(state.verification.criteria) || typeof state.verification.snapshot_hash !== 'string')) fail('bad verification');
  if (['active', 'finished'].includes(state.phase) && (!state.task || !state.baseline)) fail('active/finished run needs a task and baseline');
  if (state.task && state.review) {
    if (state.review.builder !== state.task.builder || state.review.reviewer === state.task.builder) fail('review identity violates separation');
    for (const finding of state.review.findings) {
      if (!isObject(finding) || !['block', 'major', 'minor'].includes(finding.severity)
        || typeof finding.message !== 'string' || !finding.message.trim() || typeof finding.resolved !== 'boolean') fail('bad review finding');
    }
  }
  if (state.task && state.verification) {
    const expected = state.task.packet.acceptance.map((criterion) => criterion.id).sort();
    const actual = state.verification.criteria.map((criterion) => {
      if (!isObject(criterion) || typeof criterion.id !== 'string' || !['PASS', 'FAIL', 'UNKNOWN'].includes(criterion.status)
        || typeof criterion.evidence !== 'string' || !criterion.evidence.trim()) fail('bad verification criterion');
      return criterion.id;
    }).sort();
    if (canonical(actual) !== canonical(expected)) fail('verification criteria do not match acceptance');
    if (state.verification.verifier === state.task.builder) fail('verification identity violates separation');
    if (state.pm_binding?.format === 'current' && state.review?.reviewer === state.verification.verifier) {
      fail('current shared-project verifier must differ from reviewer');
    }
    if (state.pm_binding?.format === 'current'
      && state.review?.panel?.members.some((member) => member.reviewer === state.verification.verifier)) {
      fail('current shared-project verifier must differ from every panel reviewer');
    }
  }
  if (state.contracts !== undefined && state.contracts !== null) {
    if (!isObject(state.contracts) || !isObject(state.contracts.hashes) || !isStringArray(state.contracts.specs)
      || !isStringArray(state.contracts.editable_paths)) fail('bad frozen contracts');
    for (const [rel, hash] of Object.entries(state.contracts.hashes)) {
      if (path.isAbsolute(rel) || rel.split(/[\\/]/).includes('..') || !/^[0-9a-f]{64}$/.test(hash)) fail('unsafe contract hash');
    }
  }
  return state;
}

export function currentPlanHash(state) {
  if (state.plan.path === null) return state.plan.hash;
  try { return sha256(fs.readFileSync(state.plan.path)); }
  catch { return null; }
}

export function approvalIsCurrent(state) {
  const hash = currentPlanHash(state);
  return state.approval !== null && hash !== null && state.approval.plan_hash === hash;
}

export function syncPlan(state) {
  const hash = currentPlanHash(state);
  if (hash === null) throw new DeliverError(`plan is missing or unreadable: ${state.plan.path}`, 66);
  if (hash !== state.plan.hash) {
    archiveEvidence(state, 'plan_changed', { previous_plan_hash: state.plan.hash, next_plan_hash: hash });
    state.plan.hash = hash;
    state.approval = null;
    state.events.push({ at: new Date().toISOString(), type: 'plan_changed', plan_hash: hash });
  }
  return hash;
}

function checkedDirectory(dir, create) {
  try {
    const stat = fs.lstatSync(dir);
    if (!stat.isDirectory() || stat.isSymbolicLink()) throw new DeliverError(`runtime path must be a real directory: ${dir}`, 66);
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    if (error.code !== 'ENOENT' || !create) throw new DeliverError(`runtime directory is unavailable: ${dir}`, 66);
    try { fs.mkdirSync(dir, { mode: 0o700 }); }
    catch (mkdirError) {
      if (mkdirError.code !== 'EEXIST') throw new DeliverError(`cannot create runtime directory: ${dir}`, 66);
    }
    const stat = fs.lstatSync(dir);
    if (!stat.isDirectory() || stat.isSymbolicLink()) throw new DeliverError(`runtime path must be a real directory: ${dir}`, 66);
  }
  return dir;
}

export function internalDirectory(projectRoot, segments, create = true) {
  const root = fs.realpathSync(projectRoot);
  let cursor = checkedDirectory(path.join(root, '.deliver'), create);
  for (const segment of segments) {
    if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(segment)) throw new DeliverError('unsafe runtime directory segment', 66);
    cursor = checkedDirectory(path.join(cursor, segment), create);
  }
  return cursor;
}

function runsDir(projectRoot, create = true) { return internalDirectory(projectRoot, ['runs'], create); }

function atomicWrite(file, value, exclusive = false) {
  const temp = path.join(path.dirname(file), `.${path.basename(file)}.${process.pid}.${randomUUID()}.tmp`);
  fs.writeFileSync(temp, `${JSON.stringify(value, null, 2)}\n`, { mode: 0o600, flag: 'wx' });
  const tempFd = fs.openSync(temp, 'r');
  try { fs.fsyncSync(tempFd); } finally { fs.closeSync(tempFd); }
  try {
    if (exclusive && fs.existsSync(file)) throw new DeliverError(`run state already exists: ${file}`, 66);
    fs.renameSync(temp, file);
    let dirFd;
    try {
      dirFd = fs.openSync(path.dirname(file), 'r');
      fs.fsyncSync(dirFd);
    } catch (error) {
      if (process.platform !== 'win32') throw error;
    } finally { if (dirFd !== undefined) fs.closeSync(dirFd); }
  } finally {
    try { fs.unlinkSync(temp); } catch {}
  }
}

export function createRun(projectRoot, mode, planPath = null) {
  if (!['quick', 'managed', 'governed'].includes(mode)) throw new DeliverError('mode must be quick, managed, or governed', 64);
  const root = fs.realpathSync(projectRoot);
  if (!planPath && mode !== 'quick') throw new DeliverError('--plan is required in managed and governed modes', 64);
  const plan = planPath ? path.resolve(root, planPath) : null;
  let planHash = sha256('quick:no-plan');
  if (plan !== null) {
    try { planHash = sha256(fs.readFileSync(plan)); }
    catch (error) { throw new DeliverError(`cannot read plan: ${error.message}`, 66); }
  }
  const runId = randomUUID();
  const now = new Date().toISOString();
  const state = {
    schema_version: STATE_VERSION,
    run_id: runId,
    mode,
    revision: 0,
    project_root: root,
    created_at: now,
    updated_at: now,
    phase: 'initialized',
    plan: { path: plan, hash: planHash },
    approval: null,
    task: null,
    baseline: null,
    gates: [],
    review: null,
    verification: null,
    evidence_history: [],
    checkpoints: [],
    counters: { retries: 0, fixes: 0, corrections: 0 },
    events: [{ at: now, type: 'initialized', mode, plan_hash: planHash }],
  };
  const file = path.join(runsDir(root), `${runId}.json`);
  atomicWrite(file, state, true);
  return { state, file };
}

export function resolveRunPath(runArg, cwd = process.cwd()) {
  if (!runArg) throw new DeliverError('--run is required', 64);
  if (/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(runArg)) {
    let cursor = path.resolve(cwd);
    while (true) {
      const candidate = path.join(cursor, '.deliver', 'runs', `${runArg}.json`);
      if (fs.existsSync(candidate)) return candidate;
      const parent = path.dirname(cursor);
      if (parent === cursor) break;
      cursor = parent;
    }
    return path.join(cwd, '.deliver', 'runs', `${runArg}.json`);
  }
  return path.resolve(cwd, runArg);
}

export function readRun(runArg, cwd = process.cwd()) {
  const unresolvedFile = resolveRunPath(runArg, cwd);
  let file;
  let lexicalRoot;
  try {
    const runs = path.dirname(unresolvedFile);
    const deliver = path.dirname(runs);
    if (path.basename(runs) !== 'runs' || path.basename(deliver) !== '.deliver') throw new DeliverError('run state must be under .deliver/runs', 66);
    for (const dir of [deliver, runs]) {
      const stat = fs.lstatSync(dir);
      if (!stat.isDirectory() || stat.isSymbolicLink()) throw new DeliverError(`runtime path must be a real directory: ${dir}`, 66);
    }
    const stat = fs.lstatSync(unresolvedFile);
    if (!stat.isFile() || stat.isSymbolicLink()) throw new DeliverError('run state must be a regular file, not a symlink', 66);
    lexicalRoot = fs.realpathSync(path.dirname(deliver));
    file = fs.realpathSync(unresolvedFile);
    const expected = path.join(lexicalRoot, '.deliver', 'runs', path.basename(unresolvedFile));
    if (file !== expected) throw new DeliverError('run state is outside the canonical project runs directory', 66);
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    throw new DeliverError(`cannot read run state: ${error.message}`, 66);
  }
  const state = validateRunState(readJsonFile(file, 'run state'));
  let actualRoot;
  try { actualRoot = fs.realpathSync(state.project_root); } catch { throw new DeliverError('run project root no longer exists', 66); }
  if (actualRoot !== state.project_root || actualRoot !== lexicalRoot) throw new DeliverError('run project root identity changed', 66);
  if (path.basename(file) !== `${state.run_id}.json`) throw new DeliverError('run filename does not match run_id', 66);
  return { state, file };
}

function acquireLock(file) {
  const lock = `${file}.lock`;
  let fd;
  try { fd = fs.openSync(lock, 'wx', 0o600); }
  catch (error) {
    if (error.code === 'EEXIST') throw new DeliverError(`run is locked by another process: ${lock}`, 66);
    throw error;
  }
  fs.writeFileSync(fd, `${process.pid} ${new Date().toISOString()}\n`);
  return () => { try { fs.closeSync(fd); } finally { try { fs.unlinkSync(lock); } catch {} } };
}

export function updateRun(runArg, expectedRevision, mutate, cwd = process.cwd()) {
  const file = readRun(runArg, cwd).file;
  const unlock = acquireLock(file);
  try {
    const { state } = readRun(file, cwd);
    if (expectedRevision !== undefined && state.revision !== expectedRevision) {
      throw new DeliverError(`revision conflict: expected ${expectedRevision}, found ${state.revision}`, 66);
    }
    const result = mutate(state);
    state.revision += 1;
    state.updated_at = new Date().toISOString();
    validateRunState(state);
    atomicWrite(file, state);
    return { state, file, result };
  } finally { unlock(); }
}

#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import {
  archiveEvidence,
  DeliverError,
  approvalIsCurrent,
  createRun,
  currentPlanHash,
  readJsonFile,
  readRun,
  sha256,
  syncPlan,
  updateRun,
  validateTaskPacket,
} from './lib/state.mjs';
import { baselineDirtyPaths, captureGitAnchor, gitRoot, inspectScope, snapshot, validateTaskPaths } from './lib/scope.mjs';
import { executeGate, gateIsCurrent, parseEnvironment } from './lib/gates.mjs';
import { captureContracts } from './lib/contracts.mjs';
import { preparePmBinding } from './lib/pm.mjs';
import { detectProjectFormat, inspectProjectState } from './lib/project-state.mjs';
import { adoptPreparedCommit, assertFinalCandidate, prepareCommitAdoption, transitionCurrentExecution } from './lib/transitions.mjs';
import { parseReviewReceipt } from './lib/review.mjs';

const HELP = `Deliver deterministic runtime

Usage:
  deliver.mjs help
  deliver.mjs init --mode quick [--plan <file>]
  deliver.mjs init --mode managed|governed --plan <file>
  deliver.mjs status --run <uuid|state.json>
  deliver.mjs approve --run <run> --approver <id>
  deliver.mjs start --run <run> --task <packet.json> --builder <id> [--story docs/stories/<story>.md]
  deliver.mjs check --run <run>
  deliver.mjs gate --run <run> --name <command-name> --command <exact-shell-command> [--cwd <relative-dir>] [--env <json>]
  deliver.mjs review --run <run> --snapshot <sha256> --reviewer <id> --receipt <json>
  deliver.mjs verify --run <run> --snapshot <sha256> --verifier <id> --results <json>
  deliver.mjs checkpoint --run <run> --label <text>
  deliver.mjs correct-course --run <run> --kind retry|fix|plan --reason <text> [--plan <file>]
  deliver.mjs commit-prepare --run <run>
  deliver.mjs commit-adopt --run <run> --token <uuid> --commit <full-sha>
  deliver.mjs finish --run <run>

All mutating commands accept --expected-revision <n>. Output is one JSON object.
Gate commands are intentionally authorized runtime steps. The runtime invokes the exact
--command string through the platform shell in the recorded cwd, with a 10 minute limit.
`;

const VALUE_FLAGS = new Set([
  '--mode', '--plan', '--run', '--approver', '--task', '--builder', '--expected-revision',
  '--name', '--command', '--cwd', '--env', '--reviewer', '--receipt', '--verifier', '--results',
  '--label', '--kind', '--reason', '--snapshot', '--story',
  '--token', '--commit',
]);

function args(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i++) {
    const key = argv[i];
    if (!VALUE_FLAGS.has(key)) throw new DeliverError(`unknown argument: ${key}`, 64);
    if (argv[i + 1] === undefined) throw new DeliverError(`${key} requires a value`, 64);
    if (Object.hasOwn(out, key)) throw new DeliverError(`duplicate argument: ${key}`, 64);
    out[key] = argv[++i];
  }
  if (out['--expected-revision'] !== undefined) {
    if (!/^(0|[1-9][0-9]*)$/.test(out['--expected-revision'])) throw new DeliverError('--expected-revision must be a non-negative integer', 64);
    out.expectedRevision = Number(out['--expected-revision']);
  }
  return out;
}

const required = (o, key) => {
  const value = o[key];
  if (typeof value !== 'string' || value.trim() === '') throw new DeliverError(`${key} is required`, 64);
  return value;
};

const actor = (value, flag) => {
  if (!/^[A-Za-z0-9][A-Za-z0-9._@-]{0,127}$/.test(value || '')) throw new DeliverError(`${flag} must be an explicit safe identity`, 64);
  return value;
};

const snapshotArgument = (o) => {
  const value = required(o, '--snapshot');
  if (!/^[0-9a-f]{64}$/.test(value)) throw new DeliverError('--snapshot must be a lowercase SHA-256 hash from check', 64);
  return value;
};

function event(state, type, extra = {}) {
  state.events.push({ at: new Date().toISOString(), type, ...extra });
}

function active(state) {
  if (state.phase !== 'active') throw new DeliverError(`run must be active, current phase is ${state.phase}`, 66);
}

function requireCurrentApproval(state) {
  const format = detectProjectFormat(state.project_root);
  if (format === 'current') {
    const shared = inspectProjectState(state.project_root, { actorId: null });
    if (!shared?.approval?.implementation_ready) throw new DeliverError('current project needs an approved tracked marker and matching shared plan', 66);
    const planPath = path.join(state.project_root, 'docs', 'plan.md');
    if (state.plan.path !== planPath || currentPlanHash(state) !== state.plan.hash) throw new DeliverError('runtime must use the unchanged approved shared docs/plan.md', 66);
    if (!approvalIsCurrent(state) || state.approval.source !== 'current-project'
      || state.approval.shared_plan_digest !== shared.approval.plan_digest) {
      state.approval = {
        approver: shared.approval.approver || 'shared-project',
        plan_hash: state.plan.hash,
        approved_at: shared.approval.approved_date || new Date().toISOString(),
        source: 'current-project',
        shared_plan_digest: shared.approval.plan_digest,
      };
      event(state, 'shared_approval_reused', { plan_hash: state.plan.hash, plan_digest: shared.approval.plan_digest });
    }
    return shared;
  }
  if (state.mode !== 'quick' && !approvalIsCurrent(state)) throw new DeliverError(`${state.mode} mode needs explicit approval for the current plan`, 66);
  return null;
}

function parseVerification(file, acceptance) {
  const document = readJsonFile(file, 'verification results');
  if (!document || typeof document !== 'object' || Array.isArray(document) || !Array.isArray(document.criteria)) {
    throw new DeliverError('verification results must contain a criteria array', 66);
  }
  const criteria = document.criteria.map((criterion, index) => {
    if (!criterion || typeof criterion !== 'object' || Array.isArray(criterion) || typeof criterion.id !== 'string' || !['PASS', 'FAIL', 'UNKNOWN'].includes(criterion.status) || typeof criterion.evidence !== 'string' || criterion.evidence.trim() === '') {
      throw new DeliverError(`invalid verification criterion at index ${index}`, 66);
    }
    return { id: criterion.id, status: criterion.status, evidence: criterion.evidence };
  });
  const expected = acceptance.map((item) => item.id).sort();
  const actual = criteria.map((item) => item.id).sort();
  if (new Set(actual).size !== actual.length || JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new DeliverError('verification criteria must cover each acceptance id exactly once', 66);
  }
  return criteria;
}

function summarize(state, file) {
  const planHash = currentPlanHash(state);
  let scope = null;
  if (state.baseline && state.task) {
    try { scope = inspectScope(state).report; }
    catch (error) { scope = { ok: false, error: error.message }; }
  }
  return {
    ok: true,
    run_id: state.run_id,
    state_path: file,
    revision: state.revision,
    mode: state.mode,
    phase: state.phase,
    plan: { ...state.plan, current_hash: planHash, changed: planHash !== state.plan.hash },
    approval_current: approvalIsCurrent(state),
    task_id: state.task?.packet.id || null,
    builder: state.task?.builder || null,
    scope,
    gates: state.gates.map((gate) => ({ name: gate.name, command: gate.command, status: gate.status, snapshot_hash: gate.snapshot_hash })),
    review: state.review && {
      status: state.review.status,
      builder: state.review.builder,
      reviewer: state.review.reviewer,
      snapshot_hash: state.review.snapshot_hash,
      findings: state.review.findings.length,
      unresolved_blocking: state.review.findings.filter((finding) => !finding.resolved && finding.severity !== 'minor').length,
      unresolved_minor: state.review.findings.filter((finding) => !finding.resolved && finding.severity === 'minor').length,
    },
    verification: state.verification && {
      verifier: state.verification.verifier,
      snapshot_hash: state.verification.snapshot_hash,
      counts: Object.fromEntries(['PASS', 'FAIL', 'UNKNOWN'].map((status) => [status, state.verification.criteria.filter((criterion) => criterion.status === status).length])),
    },
    counters: state.counters,
  };
}

function output(value) { process.stdout.write(`${JSON.stringify(value)}\n`); }

function main() {
  const [command = 'help', ...rest] = process.argv.slice(2);
  if (command === 'help' || command === '--help' || command === '-h') {
    process.stdout.write(HELP);
    return;
  }
  const o = args(rest);
  if (command === 'init') {
    const root = gitRoot(process.cwd());
    const format = detectProjectFormat(root);
    let plan = o['--plan'];
    if (format === 'current') {
      const sharedPlan = path.join(root, 'docs', 'plan.md');
      if (plan && path.resolve(root, plan) !== sharedPlan) throw new DeliverError('current projects must use the shared docs/plan.md', 64);
      plan = 'docs/plan.md';
    }
    const created = createRun(root, required(o, '--mode'), plan);
    if (format !== 'current') {
      output(summarize(created.state, created.file));
      return;
    }
    const shared = inspectProjectState(root, { actorId: null });
    if (!shared?.approval?.implementation_ready) {
      output(summarize(created.state, created.file));
      return;
    }
    const updated = updateRun(created.file, 0, (state) => { requireCurrentApproval(state); });
    output(summarize(updated.state, updated.file));
    return;
  }
  const run = required(o, '--run');
  if (command === 'status') {
    const loaded = readRun(run);
    output(summarize(loaded.state, loaded.file));
    return;
  }
  if (command === 'approve') {
    const approver = actor(required(o, '--approver'), '--approver');
    const updated = updateRun(run, o.expectedRevision, (state) => {
      if (detectProjectFormat(state.project_root) === 'current') {
        throw new DeliverError('current projects use pm.mjs approve; the runtime reuses that shared approval', 66);
      }
      const planHash = syncPlan(state);
      state.approval = { approver, plan_hash: planHash, approved_at: new Date().toISOString() };
      event(state, 'approved', { approver, plan_hash: planHash });
    });
    output(summarize(updated.state, updated.file));
    return;
  }
  if (command === 'start') {
    const builder = actor(required(o, '--builder'), '--builder');
    const taskPath = required(o, '--task');
    const packetInput = validateTaskPacket(readJsonFile(taskPath, 'task packet'));
    const started = updateRun(run, o.expectedRevision, (state) => {
      if (state.phase !== 'initialized') throw new DeliverError(`cannot start from phase ${state.phase}`, 66);
      syncPlan(state);
      requireCurrentApproval(state);
      const packet = validateTaskPaths(state.project_root, packetInput);
      state.pm_binding = preparePmBinding(state, packet, o['--story']);
      state.contracts = captureContracts(state.project_root, packet);
      state.task = { packet, builder, started_at: new Date().toISOString() };
      const dirtyPaths = baselineDirtyPaths(state.project_root);
      const baselineSnapshot = snapshot(state.project_root, [...packet.touches, ...packet.read_paths, ...packet.specs]);
      state.baseline = { captured_at: new Date().toISOString(), snapshot: baselineSnapshot, dirty_paths: dirtyPaths };
      if (state.pm_binding?.format === 'current') {
        state.git_anchor = captureGitAnchor(state.project_root);
        state.execution_audit = null;
        state.commit_adoption = { pending: null, history: [] };
      }
      state.phase = 'active';
      event(state, 'baseline_captured', { snapshot_hash: baselineSnapshot.hash, dirty_paths: dirtyPaths });
    });
    output(summarize(started.state, started.file));
    return;
  }
  if (command === 'check') {
    const loaded = readRun(run);
    active(loaded.state);
    const checked = inspectScope(loaded.state);
    output({ ok: checked.report.ok, run_id: loaded.state.run_id, revision: loaded.state.revision, snapshot_hash: checked.current.hash, ...checked.report });
    if (!checked.report.ok) process.exitCode = 74;
    return;
  }
  if (command === 'gate') {
    const name = required(o, '--name');
    const commandText = required(o, '--command');
    const environment = parseEnvironment(o['--env']);
    const updated = updateRun(run, o.expectedRevision, (state) => {
      active(state);
      syncPlan(state);
      requireCurrentApproval(state);
      const receipt = executeGate(state, { name, command: commandText, cwd: o['--cwd'] || '.', environment });
      state.gates.push(receipt);
      event(state, 'gate_executed', { name, status: receipt.status, snapshot_hash: receipt.snapshot_hash });
      return receipt;
    });
    output({ ok: updated.result.status === 'PASS', run_id: updated.state.run_id, revision: updated.state.revision, gate: updated.result });
    if (updated.result.status !== 'PASS') process.exitCode = 1;
    return;
  }
  if (command === 'review') {
    const reviewer = actor(required(o, '--reviewer'), '--reviewer');
    const reviewedSnapshot = snapshotArgument(o);
    const receipt = parseReviewReceipt(required(o, '--receipt'), { expectedSnapshot: reviewedSnapshot });
    const updated = updateRun(run, o.expectedRevision, (state) => {
      active(state);
      syncPlan(state);
      requireCurrentApproval(state);
      if (reviewer === state.task.builder) throw new DeliverError('reviewer must differ from builder', 66);
      const checked = inspectScope(state);
      if (!checked.report.ok) throw new DeliverError('cannot review out-of-scope changes', 74, checked.report);
      if (checked.current.hash !== reviewedSnapshot) throw new DeliverError('review snapshot is stale or does not match this run', 66);
      state.review = { ...receipt, builder: state.task.builder, reviewer, snapshot_hash: checked.current.hash, recorded_at: new Date().toISOString() };
      event(state, 'review_recorded', { reviewer, status: receipt.status, snapshot_hash: checked.current.hash });
    });
    output(summarize(updated.state, updated.file));
    return;
  }
  if (command === 'verify') {
    const verifier = actor(required(o, '--verifier'), '--verifier');
    const verifiedSnapshot = snapshotArgument(o);
    const updated = updateRun(run, o.expectedRevision, (state) => {
      active(state);
      syncPlan(state);
      requireCurrentApproval(state);
      if (verifier === state.task.builder) throw new DeliverError('verifier must differ from builder', 66);
      if (state.pm_binding?.format === 'current' && state.review?.reviewer === verifier) throw new DeliverError('current shared-project verifier must differ from reviewer', 66);
      if (state.pm_binding?.format === 'current' && state.review?.panel?.members.some((member) => member.reviewer === verifier)) {
        throw new DeliverError('current shared-project verifier must differ from every panel reviewer', 66);
      }
      if (state.mode === 'governed' && state.review?.reviewer === verifier) throw new DeliverError('governed verifier must differ from reviewer', 66);
      const criteria = parseVerification(required(o, '--results'), state.task.packet.acceptance);
      const checked = inspectScope(state);
      if (!checked.report.ok) throw new DeliverError('cannot verify out-of-scope changes', 74, checked.report);
      if (checked.current.hash !== verifiedSnapshot) throw new DeliverError('verification snapshot is stale or does not match this run', 66);
      state.verification = { verifier, criteria, snapshot_hash: checked.current.hash, recorded_at: new Date().toISOString() };
      event(state, 'verification_recorded', { verifier, snapshot_hash: checked.current.hash });
    });
    output(summarize(updated.state, updated.file));
    return;
  }
  if (command === 'checkpoint') {
    const label = required(o, '--label');
    if (label.length > 200 || /[\x00-\x1f\x7f]/.test(label)) throw new DeliverError('checkpoint label must be printable and at most 200 characters', 64);
    const updated = updateRun(run, o.expectedRevision, (state) => {
      active(state);
      const checked = inspectScope(state);
      if (!checked.report.ok) throw new DeliverError('cannot checkpoint out-of-scope changes', 74, checked.report);
      state.checkpoints.push({ label, snapshot_hash: checked.current.hash, at: new Date().toISOString() });
      event(state, 'checkpoint', { label, snapshot_hash: checked.current.hash });
    });
    output(summarize(updated.state, updated.file));
    return;
  }
  if (command === 'correct-course') {
    const kind = required(o, '--kind');
    const reason = required(o, '--reason');
    if (!['retry', 'fix', 'plan'].includes(kind)) throw new DeliverError('--kind must be retry, fix, or plan', 64);
    if (reason.length > 1000 || /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(reason)) throw new DeliverError('reason must be printable and at most 1000 characters', 64);
    const current = readRun(run);
    if (kind !== 'plan' && detectProjectFormat(current.state.project_root) === 'current') {
      const transitioned = transitionCurrentExecution(run, { to: 'building', attempt: kind, reason, expectedRevision: o.expectedRevision });
      output(summarize(transitioned.state, transitioned.file));
      return;
    }
    const updated = updateRun(run, o.expectedRevision, (state) => {
      if (state.phase === 'finished') throw new DeliverError('finished runs cannot be corrected', 66);
      if (kind === 'plan') {
        const newPlan = path.resolve(state.project_root, required(o, '--plan'));
        let hash;
        try { hash = sha256(fs.readFileSync(newPlan)); } catch (error) { throw new DeliverError(`cannot read new plan: ${error.message}`, 66); }
        state.plan = { path: newPlan, hash };
        state.approval = null;
        state.counters.corrections += 1;
      } else {
        const counter = kind === 'retry' ? 'retries' : 'fixes';
        const limit = kind === 'retry' ? 2 : 3;
        if (state.counters[counter] >= limit) throw new DeliverError(`${kind} limit of ${limit} has been reached`, 66);
        state.counters[counter] += 1;
      }
      archiveEvidence(state, 'correct_course', { kind, reason, plan_hash: state.plan.hash });
      event(state, 'correct_course', { kind, reason, plan_hash: state.plan.hash });
    });
    output(summarize(updated.state, updated.file));
    return;
  }
  if (command === 'commit-prepare') {
    const prepared = prepareCommitAdoption(run, o.expectedRevision);
    output({ ...summarize(prepared.state, prepared.file), preparation: prepared.result });
    return;
  }
  if (command === 'commit-adopt') {
    const adopted = adoptPreparedCommit(run, {
      token: required(o, '--token'), commit: required(o, '--commit'), expectedRevision: o.expectedRevision,
    });
    output({ ...summarize(adopted.state, adopted.file), adoption: adopted.result });
    return;
  }
  if (command === 'finish') {
    const updated = updateRun(run, o.expectedRevision, (state) => {
      active(state);
      syncPlan(state);
      requireCurrentApproval(state);
      const checked = inspectScope(state);
      if (!checked.report.ok) throw new DeliverError('scope check failed', 74, checked.report);
      assertFinalCandidate(state);
      if (checked.report.changed.length === 0) throw new DeliverError('cannot finish without a worktree change after the baseline', 66);
      const requiredCommands = Object.entries(state.task.packet.commands);
      for (const [name, commandText] of requiredCommands) {
        const gate = [...state.gates].reverse().find((item) => item.name === name && item.command === commandText);
        if (!gate || !gateIsCurrent(state, gate, checked.current.hash)) throw new DeliverError(`required gate is missing, failed, or stale: ${name}`, 66);
      }
      if (!state.review || state.review.status !== 'PASS' || state.review.snapshot_hash !== checked.current.hash
        || state.review.findings.some((finding) => !finding.resolved && finding.severity !== 'minor')) {
        throw new DeliverError('independent PASS review is missing, unresolved, or stale', 66);
      }
      if (!state.verification || state.verification.snapshot_hash !== checked.current.hash || state.verification.criteria.some((criterion) => criterion.status !== 'PASS')) {
        throw new DeliverError('acceptance verification is missing, non-PASS, or stale', 66);
      }
      if (state.verification.verifier === state.task.builder) throw new DeliverError('verifier must differ from builder', 66);
      if (state.pm_binding?.format === 'current' && state.verification.verifier === state.review.reviewer) throw new DeliverError('current shared-project verifier must differ from reviewer', 66);
      if (state.mode === 'governed' && state.verification.verifier === state.review.reviewer) throw new DeliverError('governed verifier must differ from reviewer', 66);
      state.phase = 'finished';
      state.completion_snapshot = checked.current;
      state.finished_at = new Date().toISOString();
      event(state, 'finished', { snapshot_hash: checked.current.hash });
    });
    output(summarize(updated.state, updated.file));
    return;
  }
  throw new DeliverError(`unknown command: ${command}`, 64);
}

try { main(); }
catch (error) {
  const known = error instanceof DeliverError;
  output({ ok: false, error: error.message || String(error), ...(error.details === undefined ? {} : { details: error.details }) });
  process.exitCode = known ? error.code : 70;
}

#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { DeliverError } from './lib/state.mjs';
import { gitRoot, snapshot } from './lib/scope.mjs';
import { initializePm, readPm, approvePm, claimPm, completePm, recoverPm, pmActorId } from './lib/pm.mjs';
import { detectProjectFormat, inspectProjectState } from './lib/project-state.mjs';
import {
  approveCurrentPm,
  assertCurrentPmReady,
  claimCurrentPm,
  initializeCurrentPm,
  recoverCurrentPm,
  revokeCurrentPm,
} from './lib/current-pm.mjs';
import { recoverExecutionTransition, transitionCurrentExecution } from './lib/transitions.mjs';
import {
  adoptIntegrationHandoff,
  adoptLocalIntegration,
  adoptStoryClosure,
  adoptVerificationReport,
  finalizeIntegrationEvidence,
  prepareIntegrationHandoff,
  prepareLocalIntegration,
  prepareStoryClosure,
  prepareVerificationReport,
  recordIntegrationReview,
  recordIntegrationVerification,
  runIntegrationGate,
} from './lib/integration.mjs';

const help = `Shared Deliver project state
  pm.mjs init [--name PROJECT] [--format current|legacy]
  pm.mjs status
  pm.mjs actor-id
  pm.mjs approve --approver ACTUAL_USER
  pm.mjs revoke [--reason TEXT]
  pm.mjs claim --story docs/stories/S1-1-example.md [--branch pm/S1-1-example]
  pm.mjs transition --run RUN --to building|built|in-review|blocked [--attempt fix|retry] [--reason TEXT]
  pm.mjs integrate-prepare --run RUN [--verification-report]
  pm.mjs integrate-adopt --integration FILE --expected-record HASH --token TOKEN --commit SHA
  pm.mjs integrate-gate --integration FILE --expected-record HASH --name GATE
  pm.mjs integrate-review --integration FILE --expected-record HASH --reviewer ID --receipt JSON
  pm.mjs integrate-verify --integration FILE --expected-record HASH --verifier ID --results JSON
  pm.mjs integrate-finalize --integration FILE --expected-record HASH
  pm.mjs report-prepare|close-prepare --integration FILE --expected-record HASH
  pm.mjs report-adopt|close-adopt --integration FILE --expected-record HASH --token TOKEN --commit SHA
  pm.mjs handoff-prepare --integration FILE --expected-record HASH [--next TEXT]
  pm.mjs handoff-adopt --integration FILE --expected-record HASH --token TOKEN --commit SHA
  pm.mjs complete --run UUID --commit FULL_INTEGRATION_SHA --next "Next ready story or decision"
  pm.mjs recover

Run in the project checkout. These commands never commit, merge, push or execute a model.
The explicit integrate-gate command executes only a gate declared by the finished source task.
Complete records a verified, committed story boundary, not an unmerged implementation.
Recover completes an interrupted journal only when every file matches its before/after image.
`;

function durableCurrentMarker(root) {
  if (fs.existsSync(path.join(root, 'docs', 'approval.json'))) return true;
  for (const args of [
    ['ls-files', '--error-unmatch', '--', 'docs/approval.json'],
    ['cat-file', '-e', 'HEAD:docs/approval.json'],
  ]) {
    try {
      execFileSync('git', ['-C', root, ...args], { stdio: 'ignore', timeout: 5000 });
      return true;
    } catch {}
  }
  return false;
}
try {
  const [command = 'help', ...rest] = process.argv.slice(2);
  if (['help', '--help', '-h'].includes(command)) process.stdout.write(help);
  else {
    const allowed = {
      init: ['--name', '--format'], status: [], 'actor-id': [], approve: ['--approver'], revoke: ['--reason'], claim: ['--story', '--branch'],
      transition: ['--run', '--to', '--attempt', '--reason', '--expected-revision'], complete: ['--run', '--commit', '--next'], recover: [],
      'integrate-prepare': ['--run', '--verification-report'], 'integrate-adopt': ['--integration', '--expected-record', '--token', '--commit'],
      'integrate-gate': ['--integration', '--expected-record', '--name'], 'integrate-review': ['--integration', '--expected-record', '--reviewer', '--receipt'],
      'integrate-verify': ['--integration', '--expected-record', '--verifier', '--results'], 'integrate-finalize': ['--integration', '--expected-record'],
      'report-prepare': ['--integration', '--expected-record'], 'report-adopt': ['--integration', '--expected-record', '--token', '--commit'],
      'close-prepare': ['--integration', '--expected-record'], 'close-adopt': ['--integration', '--expected-record', '--token', '--commit'],
      'handoff-prepare': ['--integration', '--expected-record', '--next'], 'handoff-adopt': ['--integration', '--expected-record', '--token', '--commit'],
    };
    if (!Object.hasOwn(allowed, command)) throw new DeliverError('unknown shared PM command', 64);
    const options = {};
    for (let i = 0; i < rest.length;) {
      const flag = rest[i++];
      if (!allowed[command].includes(flag) || Object.hasOwn(options, flag)) throw new DeliverError('unknown, duplicate or missing PM option', 64);
      if (flag === '--verification-report') options[flag] = true;
      else {
        if (!rest[i]) throw new DeliverError('unknown, duplicate or missing PM option', 64);
        options[flag] = rest[i++];
      }
    }
    const root = gitRoot(process.cwd());
    const format = detectProjectFormat(root);
    let result;
    if (command === 'init') {
      const requested = options['--format'];
      if (requested !== undefined && !['current', 'legacy'].includes(requested)) throw new DeliverError('--format must be current or legacy', 64);
      if (format === 'legacy' && requested === 'current') throw new DeliverError('explicit migration is required before converting a legacy project to current format', 66);
      if (format === 'current' && requested === 'legacy') {
        const current = inspectProjectState(root, { actorId: null });
        const executionEvidence = current?.stories.some((story) => story.execution !== null);
        if (durableCurrentMarker(root) || executionEvidence) throw new DeliverError('current projects cannot initialize legacy state alongside current artifacts', 66);
      }
      const selected = requested || (format === 'legacy' ? 'legacy' : 'current');
      result = selected === 'legacy' ? initializePm(root, options['--name']) : initializeCurrentPm(root, options['--name']);
    }
    else if (command === 'status') {
      assertCurrentPmReady(root);
      if (format === 'current') result = inspectProjectState(root);
      else {
        const shared = readPm(root);
        result = { managed: Boolean(shared), ...shared };
      }
    }
    else if (command === 'actor-id') result = { actor: pmActorId(root) };
    else if (command === 'approve') result = format === 'current'
      ? approveCurrentPm(root, options['--approver']) : approvePm(root, options['--approver']);
    else if (command === 'revoke') {
      if (format !== 'current') throw new DeliverError('revoke is available for current-format projects', 66);
      result = revokeCurrentPm(root, options['--reason']);
    }
    else if (command === 'claim') result = format === 'current'
      ? claimCurrentPm(root, options['--story'], options['--branch']) : claimPm(root, options['--story'], options['--branch']);
    else if (command === 'transition') {
      if (format !== 'current') throw new DeliverError('Execution transitions require a current-format project', 66);
      const revision = options['--expected-revision'];
      if (revision !== undefined && !/^(0|[1-9][0-9]*)$/.test(revision)) throw new DeliverError('--expected-revision must be a non-negative integer', 64);
      const transitioned = transitionCurrentExecution(options['--run'], {
        to: options['--to'], attempt: options['--attempt'], reason: options['--reason'],
        expectedRevision: revision === undefined ? undefined : Number(revision),
      }, root);
      result = {
        run_id: transitioned.state.run_id,
        revision: transitioned.state.revision,
        story: transitioned.state.pm_binding.story,
        status: transitioned.execution.status,
        rounds: transitioned.execution.rounds,
        retries: transitioned.execution.retries,
        noop: transitioned.noop,
      };
    }
    else if (command === 'complete') {
      if (format === 'current') throw new DeliverError('current story completion requires the integration workflow', 66);
      result = completePm(root, options['--run'], options['--commit'], options['--next'], snapshot);
    }
    else if (command === 'integrate-prepare') result = prepareLocalIntegration(options['--run'], {
      integrationRoot: root, verificationReport: options['--verification-report'] === true,
    }, root);
    else if (command === 'integrate-adopt') result = adoptLocalIntegration(options['--integration'], {
      expectedRecordHash: options['--expected-record'], token: options['--token'], commit: options['--commit'],
    }, root);
    else if (command === 'integrate-gate') result = runIntegrationGate(options['--integration'], {
      expectedRecordHash: options['--expected-record'], name: options['--name'],
    }, root);
    else if (command === 'integrate-review') result = recordIntegrationReview(options['--integration'], {
      expectedRecordHash: options['--expected-record'], reviewer: options['--reviewer'], receipt: options['--receipt'],
    }, root);
    else if (command === 'integrate-verify') result = recordIntegrationVerification(options['--integration'], {
      expectedRecordHash: options['--expected-record'], verifier: options['--verifier'], results: options['--results'],
    }, root);
    else if (command === 'integrate-finalize') result = finalizeIntegrationEvidence(options['--integration'], {
      expectedRecordHash: options['--expected-record'],
    }, root);
    else if (command === 'report-prepare') result = prepareVerificationReport(options['--integration'], {
      expectedRecordHash: options['--expected-record'],
    }, root);
    else if (command === 'report-adopt') result = adoptVerificationReport(options['--integration'], {
      expectedRecordHash: options['--expected-record'], token: options['--token'], commit: options['--commit'],
    }, root);
    else if (command === 'close-prepare') result = prepareStoryClosure(options['--integration'], {
      expectedRecordHash: options['--expected-record'],
    }, root);
    else if (command === 'close-adopt') result = adoptStoryClosure(options['--integration'], {
      expectedRecordHash: options['--expected-record'], token: options['--token'], commit: options['--commit'],
    }, root);
    else if (command === 'handoff-prepare') result = prepareIntegrationHandoff(options['--integration'], {
      expectedRecordHash: options['--expected-record'], next: options['--next'],
    }, root);
    else if (command === 'handoff-adopt') result = adoptIntegrationHandoff(options['--integration'], {
      expectedRecordHash: options['--expected-record'], token: options['--token'], commit: options['--commit'],
    }, root);
    else {
      result = recoverExecutionTransition(root);
      if (!result.recovered) result = recoverCurrentPm(root);
      if (!result.recovered) result = recoverPm(root);
    }
    process.stdout.write(`${JSON.stringify({ ok: true, ...result })}\n`);
  }
} catch (error) {
  process.stdout.write(`${JSON.stringify({ ok: false, error: error.message })}\n`);
  process.exitCode = error instanceof DeliverError ? error.code : 70;
}

import fs from 'node:fs';
import path from 'node:path';
import { canonical, DeliverError, sha256 } from './state.mjs';

const MAX_STORY_BYTES = 8 * 1024 * 1024;
const EXECUTION_STATUSES = new Set(['claimed', 'building', 'built', 'in-review', 'blocked', 'merged']);
const BUILDERS = new Set(['auto', 'codex-builder', 'expert-builder']);
const RESERVED_KEYS = new Set(['__proto__', 'constructor', 'prototype']);
const fail = (message) => { throw new DeliverError(message, 66); };
const record = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);

function safeRelative(rel, label, prefix = null) {
  if (typeof rel !== 'string' || !rel || path.isAbsolute(rel) || /^[A-Za-z]:/.test(rel) || /[\x00-\x1f\x7f]/.test(rel)) fail(`unsafe ${label}`);
  const parts = rel.split(/[\\/]/);
  if (parts.some((part) => !part || part === '.' || part === '..')) fail(`unsafe ${label}`);
  const normalized = parts.join('/');
  if (prefix && !normalized.startsWith(prefix)) fail(`unsafe ${label}`);
  return normalized;
}

function storyPath(relPath) {
  const rel = safeRelative(relPath, 'story path', 'docs/stories/');
  if (!/^docs\/stories\/S\d+-\d+-[^/]+\.md$/.test(rel)) fail('story path must be docs/stories/S<digits>-<digits>-<name>.md');
  return rel;
}

function scopePath(value) {
  const rel = safeRelative(value, 'story touch path');
  if (/[?*\[\]{}<>]/.test(rel) || rel === '.git' || rel.startsWith('.git/')
    || rel === '.deliver' || rel.startsWith('.deliver/')) fail('story touch paths must be bounded repository paths');
  return rel;
}

function validateJson(value, label, depth = 0) {
  if (depth > 16) fail(`${label} is nested too deeply`);
  if (typeof value === 'string' && (value.length > 65536 || /[\x00-\x1f\x7f]/.test(value))) fail(`unsafe value in ${label}`);
  if (typeof value === 'number' && !Number.isFinite(value)) fail(`unsafe value in ${label}`);
  if (Array.isArray(value)) {
    for (const item of value) validateJson(item, label, depth + 1);
    return;
  }
  if (!record(value)) return;
  for (const [key, item] of Object.entries(value)) {
    if (RESERVED_KEYS.has(key) || /[\x00-\x1f\x7f]/.test(key)) fail(`unsafe field in ${label}`);
    validateJson(item, label, depth + 1);
  }
}

function parseCommentJson(text, kind) {
  const start = new RegExp(`<!--\\s*${kind}\\s*:`, 'g');
  const starts = [...text.matchAll(start)];
  const comments = [];
  for (const match of text.matchAll(/<!--([\s\S]*?)-->/g)) {
    const body = match[1].trim();
    if (!body.startsWith(`${kind}:`)) continue;
    comments.push({ raw: match[0], body: body.slice(kind.length + 1).trim(), index: match.index, end: match.index + match[0].length });
  }
  if (starts.length !== comments.length) fail(`malformed ${kind} comment`);
  if (comments.length !== 1) fail(`story needs exactly one ${kind} comment`);
  if (/\r|\n/.test(comments[0].body)) fail(`${kind} must contain one-line JSON`);
  let value;
  try { value = JSON.parse(comments[0].body); } catch { fail(`invalid JSON in ${kind}`); }
  if (!record(value)) fail(`${kind} must be a JSON object`);
  validateJson(value, kind);
  return { ...comments[0], value };
}

function optionalExecComment(text) {
  const starts = [...text.matchAll(/<!--\s*pm-exec\s*:/g)];
  const comments = [];
  for (const match of text.matchAll(/<!--([\s\S]*?)-->/g)) {
    const body = match[1].trim();
    if (!body.startsWith('pm-exec:')) continue;
    comments.push({ raw: match[0], body: body.slice('pm-exec:'.length).trim(), index: match.index, end: match.index + match[0].length });
  }
  if (starts.length !== comments.length) fail('malformed pm-exec comment');
  if (comments.length > 1) fail('story has duplicate pm-exec comments');
  if (!comments.length) return null;
  if (/\r|\n/.test(comments[0].body)) fail('pm-exec must contain one-line JSON');
  let value;
  try { value = JSON.parse(comments[0].body); } catch { fail('invalid JSON in pm-exec'); }
  if (!record(value)) fail('pm-exec must be a JSON object');
  validateJson(value, 'pm-exec');
  return { ...comments[0], value };
}

function cleanString(value, label, max = 512) {
  if (typeof value !== 'string' || !value || value.length > max || /[\x00-\x1f\x7f]/.test(value)) fail(`invalid ${label}`);
  return value;
}

export function isValidGitBranchName(value) {
  if (typeof value !== 'string' || !value || value.length > 512 || value === '@'
    || value.startsWith('-') || value.startsWith('/') || value.endsWith('/') || value.endsWith('.')
    || value.includes('..') || value.includes('//') || value.includes('@{')
    || /[\x00-\x20\x7f~^:?*[\\\]]/.test(value)) return false;
  return value.split('/').every((part) => part && !part.startsWith('.') && !part.endsWith('.lock'));
}

function normalizeMeta(meta) {
  if (!BUILDERS.has(meta.builder) || !Array.isArray(meta.touches) || !meta.touches.length) fail('invalid story pm-meta builder or touches');
  const touches = meta.touches.map(scopePath);
  if (new Set(touches).size !== touches.length) fail('story pm-meta touches must be unique');
  return { ...meta, builder: meta.builder, touches };
}

function normalizeExecution(value) {
  validateJson(value, 'pm-exec');
  const required = ['owner', 'builder', 'branch', 'status', 'rounds', 'retries', 'updated'];
  if (!required.every((key) => Object.hasOwn(value, key))) fail('pm-exec is missing required fields');
  cleanString(value.owner, 'pm-exec owner', 256);
  if (!['codex-builder', 'expert-builder'].includes(value.builder)) fail('invalid pm-exec builder');
  if (!isValidGitBranchName(value.branch)) fail('invalid pm-exec branch');
  if (!EXECUTION_STATUSES.has(value.status)) fail('invalid pm-exec status');
  for (const key of ['rounds', 'retries']) {
    if (!Number.isSafeInteger(value[key]) || value[key] < 0) fail(`invalid pm-exec ${key}`);
  }
  cleanString(value.updated, 'pm-exec updated', 128);
  return { ...value };
}

function sections(text, heading) {
  const source = heading === 'Execution'
    ? '^## Execution[ \\t]*\\r?$'
    : '^## Acceptance criteria(?: \\(testable\\))?[ \\t]*\\r?$';
  const re = new RegExp(source, 'gm');
  return [...text.matchAll(re)].map((match) => ({ index: match.index, end: match.index + match[0].length, raw: match[0] }));
}

function executionSection(text) {
  const found = sections(text, 'Execution');
  if (found.length > 1) fail('story has duplicate Execution sections');
  if (!found.length) return null;
  const section = found[0];
  if (/^## /m.test(text.slice(section.end).replace(/^\r?\n/, ''))) fail('Execution must be the final level-two section');
  return { start: section.index, headingEnd: section.end, end: text.length };
}

function splitList(value, label, pattern) {
  if (value.trim().toLowerCase() === 'none') return [];
  const items = value.split(',').map((item) => item.trim());
  if (!items.length || items.some((item) => !pattern.test(item)) || new Set(items).size !== items.length) fail(`invalid ${label}`);
  return items;
}

function parseHeaders(text, id) {
  const sprint = Number(id.match(/^S(\d+)-/)[1]);
  let priority = null;
  let covers = [];
  let dependsOn = [];
  let parallelSafe = null;
  let risk = null;
  let reviewLenses = [];
  let specs = [];
  const sprintLines = [...text.matchAll(/^Sprint:.*$/gm)];
  if (sprintLines.length > 1) fail('story has duplicate Sprint headers');
  if (sprintLines.length) {
    const match = sprintLines[0][0].match(/^Sprint:\s*(\d+)\s*·\s*Priority:\s*(high|med|low)\s*·\s*Covers:\s*(.*?)\s*·\s*Depends on:\s*(.*?)\s*·\s*Parallel-safe:\s*(yes|no)\s*$/);
    if (!match || Number(match[1]) !== sprint) fail('invalid story Sprint header');
    priority = match[2];
    covers = splitList(match[3], 'story Covers header', /^(?:US|FR|AC|SM)-\d+$/);
    dependsOn = splitList(match[4], 'story Depends on header', /^S\d+-\d+$/);
    parallelSafe = match[5] === 'yes';
  }
  const riskLines = [...text.matchAll(/^Risk:.*$/gm)];
  if (riskLines.length > 1) fail('story has duplicate Risk headers');
  if (riskLines.length) {
    const match = riskLines[0][0].match(/^Risk:\s*(low|med|high)\s*·\s*Review lenses:\s*(.*?)(?:\s*·\s*Specs:\s*(.*?))?\s*$/);
    if (!match) fail('invalid story Risk header');
    risk = match[1];
    reviewLenses = splitList(match[2], 'story Review lenses header', /^[a-z][a-z0-9-]*$/);
    specs = match[3] === undefined ? [] : splitList(match[3], 'story Specs header', /^(?!\/)[^\x00-\x1f\x7f*?\[\]{}<>]+\.sdd$/)
      .map((item) => safeRelative(item, 'story spec path'));
  }
  return { sprint, priority, covers, dependsOn, parallelSafe, risk, reviewLenses, specs };
}

function acceptanceCriteria(text) {
  const found = sections(text, 'Acceptance criteria');
  if (found.length !== 1) fail('story needs exactly one Acceptance criteria section');
  const start = found[0].end + (text.slice(found[0].end).match(/^\r?\n/)?.[0].length || 0);
  const next = text.slice(start).search(/^## /m);
  const end = next < 0 ? text.length : start + next;
  const criteria = [];
  for (const match of text.slice(start, end).matchAll(/^- \[([ xX])\] ([^\r\n]*)\r?$/gm)) {
    if (!match[2]) fail('acceptance criterion text must not be empty');
    const absolute = start + match.index;
    criteria.push({
      text: match[2],
      checked: match[1].toLowerCase() === 'x',
      line: text.slice(0, absolute).split(/\r?\n/).length,
    });
  }
  if (!criteria.length) fail('story needs explicit acceptance checkboxes');
  return criteria;
}

export function parseStory(text, relPath) {
  const rel = storyPath(relPath);
  if (typeof text !== 'string' || Buffer.byteLength(text) > MAX_STORY_BYTES || text.includes('\0')) fail('invalid or oversized story text');
  const heading = text.match(/^#\s+(S\d+-\d+)(?::|\s+[—-])\s*([^\r\n]+)\r?$/m);
  if (!heading || !heading[2] || /[\x00-\x1f\x7f]/.test(heading[2])) fail('story needs an ID and title heading');
  const fileId = path.basename(rel).match(/^(S\d+-\d+)-/)[1];
  if (heading[1] !== fileId) fail('story heading ID does not match its path');
  const metaComment = parseCommentJson(text, 'pm-meta');
  const metaLine = text.slice(0, metaComment.index).split(/\r?\n/).length;
  if (metaLine > 12) fail('pm-meta must appear in the first 12 lines');
  const meta = normalizeMeta(metaComment.value);
  const section = executionSection(text);
  const execComment = optionalExecComment(text);
  if (execComment && (!section || execComment.index < section.headingEnd)) fail('pm-exec must be inside the final Execution section');
  const execution = execComment ? normalizeExecution(execComment.value) : null;
  const contractText = section ? text.slice(0, section.start) : text;
  const headers = parseHeaders(contractText, heading[1]);
  const acceptance = acceptanceCriteria(contractText);
  return {
    id: heading[1],
    path: rel,
    title: heading[2],
    text,
    textHash: sha256(text),
    contractHash: sha256(contractText),
    meta,
    ...headers,
    acceptance,
    execution,
    executionHash: execution ? sha256(canonical(execution)) : null,
  };
}

export function readStory(root, relPath) {
  const rel = storyPath(relPath);
  let realRoot;
  try {
    const stat = fs.lstatSync(root);
    if (!stat.isDirectory() || stat.isSymbolicLink()) fail('project root must be a real directory');
    realRoot = fs.realpathSync.native(root);
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    fail(`cannot read project root: ${error.message}`);
  }
  let cursor = realRoot;
  for (const part of rel.split('/')) {
    cursor = path.join(cursor, part);
    let stat;
    try { stat = fs.lstatSync(cursor); } catch (error) { fail(`cannot read story ${rel}: ${error.message}`); }
    if (stat.isSymbolicLink()) fail(`story path is a symlink: ${rel}`);
  }
  let stat;
  try { stat = fs.statSync(cursor); } catch (error) { fail(`cannot read story ${rel}: ${error.message}`); }
  if (!stat.isFile() || stat.size > MAX_STORY_BYTES) fail(`story must be a regular file no larger than ${MAX_STORY_BYTES} bytes: ${rel}`);
  return parseStory(fs.readFileSync(cursor, 'utf8'), rel);
}

export function storyTaskContract(document) {
  if (!record(document) || typeof document.contractHash !== 'string' || !record(document.meta) || !Array.isArray(document.acceptance)) fail('invalid StoryDocument');
  return {
    id: document.id,
    acceptanceText: document.acceptance.map((criterion) => criterion.text),
    touches: [...document.meta.touches],
    builder: document.meta.builder,
    specs: [...document.specs],
  };
}

export function replaceStoryExecution(document, nextExec, { note } = {}) {
  if (!record(document) || typeof document.text !== 'string' || typeof document.path !== 'string') fail('invalid StoryDocument');
  if (!record(nextExec)) fail('next execution must be a JSON object');
  const merged = normalizeExecution({ ...(document.execution || {}), ...nextExec });
  if (note !== undefined) cleanString(note, 'Execution note', 1000);
  const currentSection = executionSection(document.text);
  const currentComment = optionalExecComment(document.text);
  let retained = '';
  let prefix = document.text;
  if (currentSection) {
    prefix = document.text.slice(0, currentSection.start);
    retained = document.text.slice(currentSection.headingEnd).replace(/^\r?\n/, '');
    if (currentComment) {
      const offset = currentSection.headingEnd + (document.text.slice(currentSection.headingEnd).match(/^\r?\n/)?.[0].length || 0);
      const start = currentComment.index - offset;
      retained = `${retained.slice(0, start)}${retained.slice(start + currentComment.raw.length)}`;
    }
    retained = retained.replace(/^\r?\n+/, '').replace(/\s+$/, '');
  } else if (!prefix.endsWith('\n')) prefix += '\n';
  const lines = [`<!-- pm-exec: ${JSON.stringify(merged)} -->`];
  if (retained) lines.push(retained);
  if (note !== undefined) lines.push(`- ${note}`);
  const after = `${prefix}## Execution\n${lines.join('\n')}\n`;
  const nextDocument = parseStory(after, document.path);
  if (nextDocument.contractHash !== document.contractHash) fail('Execution replacement changed the story contract');
  return {
    before: document.text,
    after,
    contractHash: nextDocument.contractHash,
    executionHash: nextDocument.executionHash,
    document: nextDocument,
  };
}

import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { DeliverError } from './state.mjs';
import { isValidGitBranchName, readStory } from './story.mjs';

const APPROVAL = 'docs/approval.json';
const PLAN = 'docs/plan.md';
const MAX_ARTIFACT_BYTES = 8 * 1024 * 1024;
const PHASES = {
  migration: 'references/migrations.md',
  discovery: 'references/discovery.md',
  retrospective: 'references/retrospective.md',
  specification: 'references/specification.md',
  planning: 'references/planning-and-signoff.md',
  decomposition: 'references/decomposition.md',
  implementation: 'references/implementation-loop.md',
  done: 'references/documentation.md',
};
const fail = (message) => { throw new DeliverError(message, 66); };
const record = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const chomp = (value) => value.replace(/(\r?\n)+$/, '');

function rootPath(root) {
  try {
    const stat = fs.lstatSync(root);
    if (!stat.isDirectory() || stat.isSymbolicLink()) fail('project root must be a real directory');
    return fs.realpathSync.native(root);
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    fail(`cannot inspect project root: ${error.message}`);
  }
}

function relativePath(rel) {
  if (typeof rel !== 'string' || !rel || path.isAbsolute(rel) || /[\x00-\x1f\x7f]/.test(rel)) fail('unsafe project artifact path');
  const parts = rel.split(/[\\/]/);
  if (parts.some((part) => !part || part === '.' || part === '..')) fail('unsafe project artifact path');
  return parts.join('/');
}

function artifactPath(root, rel) {
  const realRoot = rootPath(root);
  const normalized = relativePath(rel);
  let cursor = realRoot;
  for (const part of normalized.split('/')) {
    cursor = path.join(cursor, part);
    let stat;
    try { stat = fs.lstatSync(cursor); } catch (error) {
      if (error.code === 'ENOENT') return { path: cursor, rel: normalized, missing: true };
      throw error;
    }
    if (stat.isSymbolicLink()) fail(`project artifact path is a symlink: ${normalized}`);
  }
  return { path: cursor, rel: normalized, missing: false };
}

function readRegular(root, rel) {
  const resolved = artifactPath(root, rel);
  if (resolved.missing) return null;
  const stat = fs.statSync(resolved.path);
  if (!stat.isFile() || stat.size > MAX_ARTIFACT_BYTES) fail(`project artifact must be a regular file no larger than ${MAX_ARTIFACT_BYTES} bytes: ${resolved.rel}`);
  return fs.readFileSync(resolved.path, 'utf8');
}

function git(root, args) {
  try {
    return { ok: true, stdout: execFileSync('git', ['-C', root, ...args], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
      timeout: 5000,
      windowsHide: true,
    }) };
  } catch {
    return { ok: false, stdout: '' };
  }
}

function tracked(root, rel) {
  const result = git(root, ['ls-files', '--error-unmatch', '--', rel]);
  if (result.ok) return true;
  const inside = git(root, ['rev-parse', '--is-inside-work-tree']);
  return inside.ok && chomp(inside.stdout) === 'true' ? false : null;
}

function pathExists(root, rel) {
  try {
    const resolved = artifactPath(root, rel);
    return !resolved.missing;
  } catch {
    return true;
  }
}

function parseJsonObject(text, label) {
  let value;
  try { value = JSON.parse(text); } catch { fail(`invalid JSON in ${label}`); }
  if (!record(value)) fail(`${label} must contain a JSON object`);
  return value;
}

function optionalString(value, label, max = 512) {
  if (value !== null && value !== undefined
    && (typeof value !== 'string' || value.length > max || /[\x00-\x1f\x7f]/.test(value))) fail(`invalid ${label}`);
}

export function readApprovalMarker(root) {
  const text = readRegular(root, APPROVAL);
  if (text === null) return null;
  const marker = parseJsonObject(text, APPROVAL);
  if (!['pending', 'approved', 'revoked'].includes(marker.status)) fail('invalid approval status');
  optionalString(marker.approver, 'approval approver', 256);
  optionalString(marker.approved_date, 'approval date', 128);
  optionalString(marker.updated, 'approval updated time', 128);
  if (marker.plan_digest !== null && marker.plan_digest !== undefined
    && (typeof marker.plan_digest !== 'string' || !/^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(marker.plan_digest))) fail('invalid approval plan_digest');
  return marker;
}

function onePlanValue(text, label) {
  const matches = [...text.matchAll(new RegExp(`^- ${label}:[ \\t]*([^\\r\\n]*?)[ \\t]*(?:<!--.*-->)?[ \\t]*\\r?$`, 'gm'))];
  if (matches.length > 1) fail(`duplicate plan ${label}`);
  return matches.length ? matches[0][1].trim() : null;
}

export function readPlanPolicy(root) {
  const text = readRegular(root, PLAN);
  if (text === null) return null;
  const scale = onePlanValue(text, 'Scale');
  const checkpointPolicy = onePlanValue(text, 'Checkpoint policy');
  const integrationBranch = onePlanValue(text, 'Integration branch');
  const skeleton = onePlanValue(text, 'Skeleton');
  if (scale !== null && !['tiny', 'small', 'standard', 'large', 'regulated'].includes(scale)) fail('invalid plan Scale');
  if (checkpointPolicy !== null && !['story-level', 'sprint-level', 'autonomous'].includes(checkpointPolicy)) fail('invalid plan Checkpoint policy');
  if (integrationBranch !== null && !isValidGitBranchName(integrationBranch)) fail('invalid plan Integration branch');
  if (skeleton !== null && !['specdd', 'none'].includes(skeleton)) fail('invalid plan Skeleton');
  return { path: PLAN, scale, checkpointPolicy, integrationBranch, skeleton };
}

function storyDirectory(root) {
  try {
    const resolved = artifactPath(root, 'docs/stories');
    if (resolved.missing) return null;
    const stat = fs.statSync(resolved.path);
    if (!stat.isDirectory()) fail('docs/stories must be a real directory');
    return resolved.path;
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    fail(`cannot inspect docs/stories: ${error.message}`);
  }
}

function recognizableStory(root) {
  let dir;
  try { dir = storyDirectory(root); } catch { return { meta: false, exec: false }; }
  if (!dir) return { meta: false, exec: false };
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return { meta: false, exec: false }; }
  const found = { meta: false, exec: false };
  for (const entry of entries) {
    if (!entry.isFile() || !/^S\d+-\d+-.*\.md$/.test(entry.name)) continue;
    try {
      const stat = fs.lstatSync(path.join(dir, entry.name));
      if (!stat.isFile() || stat.isSymbolicLink() || stat.size > MAX_ARTIFACT_BYTES) continue;
      const text = fs.readFileSync(path.join(dir, entry.name), 'utf8');
      if (/<!--\s*pm-meta\s*:/.test(text)) found.meta = true;
      if (/<!--\s*pm-exec\s*:/.test(text)) found.exec = true;
    } catch {}
  }
  return found;
}

export function detectProjectFormat(root) {
  const realRoot = rootPath(root);
  if (pathExists(realRoot, APPROVAL)) return 'current';
  if (tracked(realRoot, APPROVAL) === true || git(realRoot, ['cat-file', '-e', `HEAD:${APPROVAL}`]).ok) return 'current';
  const storyMarkers = recognizableStory(realRoot);
  if (storyMarkers.exec) return 'current';
  if (pathExists(realRoot, 'pm/pm-state.json') || pathExists(realRoot, 'tmp/pm-state.json')) return 'legacy';
  if (storyMarkers.meta) return 'current';
  return 'none';
}

function cksum(text) {
  const bytes = Buffer.from(text);
  let crc = 0;
  const add = (byte) => {
    crc = (crc ^ (byte << 24)) >>> 0;
    for (let bit = 0; bit < 8; bit++) crc = ((crc << 1) ^ (crc & 0x80000000 ? 0x04c11db7 : 0)) >>> 0;
  };
  for (const byte of bytes) add(byte);
  for (let size = bytes.length; size > 0; size = Math.floor(size / 256)) add(size & 255);
  return ~crc >>> 0;
}

function actorIdentity(root) {
  let source = '';
  for (const key of ['user.email', 'user.name']) {
    const result = git(root, ['config', key]);
    if (result.ok) source = chomp(result.stdout);
    if (source) break;
  }
  if (!source) return null;
  source = source.replace(/[A-Z]/g, (letter) => letter.toLowerCase());
  const slug = source.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  if (!slug) return null;
  const first = cksum(source).toString(16).padStart(8, '0');
  const second = cksum(`${source}:pm-skill`).toString(16).padStart(8, '0');
  return `${slug}-${(first + second).slice(0, 12)}`;
}

function baseState(format, actor) {
  return {
    managed: true,
    legacy: null,
    approval: null,
    phase: null,
    next_reference: null,
    actor,
    branch: null,
    story: null,
    unmerged: [],
    unreadable: [],
    claims: [],
    sprints_without_retro: [],
    worktrees: 0,
    uncommitted: null,
    handoff: null,
    wiki_entries: null,
    format,
    current_sprint: null,
    plan: null,
    stories: [],
    diagnostics: [],
  };
}

function diagnostic(out, code, status, rel, message) {
  const item = { code, status, path: rel, message };
  if (!out.diagnostics.some((existing) => JSON.stringify(existing) === JSON.stringify(item))) out.diagnostics.push(item);
}

function inspectLegacy(root, actor) {
  const out = baseState('legacy', actor);
  out.legacy = pathExists(root, 'pm/pm-state.json') ? 'pm/pm-state.json' : 'tmp/pm-state.json';
  out.phase = 'migration';
  out.next_reference = PHASES.migration;
  return out;
}

function regularExists(out, root, rel, code) {
  try { return readRegular(root, rel) !== null; }
  catch (error) {
    diagnostic(out, code, 'UNKNOWN', rel, error.message);
    return false;
  }
}

export function inspectProjectState(root, { actorId } = {}) {
  const realRoot = rootPath(root);
  const format = detectProjectFormat(realRoot);
  if (format === 'none') return null;
  let actor = actorId === undefined ? actorIdentity(realRoot) : actorId;
  const invalidActor = actor !== null && (typeof actor !== 'string' || !/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(actor));
  if (invalidActor) actor = null;
  if (format === 'legacy') return inspectLegacy(realRoot, actor);
  const out = baseState('current', actor);
  if (invalidActor) diagnostic(out, 'ACTOR_ID_INVALID', 'UNKNOWN', '.git/config', 'The supplied actor identity is unsafe.');
  let marker = null;
  try { marker = readApprovalMarker(realRoot); }
  catch (error) { diagnostic(out, 'APPROVAL_UNREADABLE', 'UNKNOWN', APPROVAL, error.message); }
  if (!marker) diagnostic(out, 'APPROVAL_MISSING', 'MISSING', APPROVAL, 'Current-format project has no readable approval marker.');

  let planText = null;
  try { planText = readRegular(realRoot, PLAN); }
  catch (error) { diagnostic(out, 'PLAN_UNREADABLE', 'UNKNOWN', PLAN, error.message); }
  if (planText !== null) {
    try { out.plan = readPlanPolicy(realRoot); }
    catch (error) { diagnostic(out, 'PLAN_POLICY_INVALID', 'DRIFT', PLAN, error.message); }
  }

  const markerTracked = tracked(realRoot, APPROVAL);
  const planTracked = tracked(realRoot, PLAN);
  const digestResult = planText === null ? { ok: false, stdout: '' } : git(realRoot, ['hash-object', '--', PLAN]);
  const digestNow = digestResult.ok ? chomp(digestResult.stdout) : null;
  if (marker) {
    const digest = typeof marker.plan_digest === 'string' && marker.plan_digest ? marker.plan_digest : null;
    const planChanged = Boolean(marker.status === 'approved' && digest && digestNow && digest !== digestNow);
    const implementationReady = marker.status === 'approved' && markerTracked === true && planTracked === true
      && planText !== null && digest !== null && digestNow !== null && digest === digestNow;
    out.approval = {
      status: marker.status,
      approver: marker.approver ?? null,
      approved_date: marker.approved_date ?? null,
      plan_digest: digest,
      plan_changed: planChanged,
      marker_tracked: markerTracked,
      plan_tracked: planTracked,
      implementation_ready: implementationReady,
    };
    if (!implementationReady) {
      const status = markerTracked === null || planTracked === null || (planText !== null && digestNow === null) ? 'UNKNOWN'
        : marker.status !== 'approved' || !digest || planText === null ? 'MISSING' : 'DRIFT';
      diagnostic(out, 'APPROVAL_NOT_EXECUTABLE', status, APPROVAL,
        'Implementation requires an approved tracked marker, a tracked regular plan, and a matching non-null Git blob digest.');
    }
  }
  if (markerTracked === null || planTracked === null) diagnostic(out, 'GIT_TRACKING_UNKNOWN', 'UNKNOWN', '.git/index', 'Git tracking state could not be read.');

  let names = [];
  try {
    const dir = storyDirectory(realRoot);
    if (dir) names = fs.readdirSync(dir, { withFileTypes: true })
      .filter((entry) => /^S\d+-\d+-.*\.md$/.test(entry.name))
      .map((entry) => entry.name)
      .sort();
  } catch (error) { diagnostic(out, 'STORIES_UNREADABLE', 'UNKNOWN', 'docs/stories', error.message); }

  const storySlots = [];
  for (const name of names) {
    const id = name.match(/^(S\d+-\d+)-/)[1];
    const rel = `docs/stories/${name}`;
    try {
      const document = readStory(realRoot, rel);
      out.stories.push(document);
      storySlots.push({ id, document });
    } catch (error) {
      out.unreadable.push(id);
      storySlots.push({ id, document: null });
      diagnostic(out, 'STORY_UNREADABLE', 'UNKNOWN', rel, error.message);
    }
  }

  const branchResult = git(realRoot, ['branch', '--show-current']);
  out.branch = branchResult.ok ? (chomp(branchResult.stdout) || 'DETACHED') : 'DETACHED';
  if (!branchResult.ok) diagnostic(out, 'GIT_BRANCH_UNKNOWN', 'UNKNOWN', '.git/HEAD', 'Current Git branch could not be read.');
  const mine = storySlots.find(({ document }) => document?.execution?.branch === out.branch)
    || storySlots.find(({ id }) => out.branch.startsWith(`pm/${id}-`));
  if (mine) out.story = { id: mine.id, exec: mine.document?.execution ?? null };
  out.unmerged = storySlots.filter(({ document }) => !document || document.execution?.status !== 'merged').map(({ id }) => id);
  out.claims = storySlots.filter((slot) => slot !== mine && slot.document?.execution?.status && slot.document.execution.status !== 'merged')
    .map(({ id, document }) => ({ id, owner: document.execution.owner, status: document.execution.status, branch: document.execution.branch }));

  const worktreeResult = git(realRoot, ['worktree', 'list', '--porcelain']);
  if (worktreeResult.ok) out.worktrees = Math.max(0, worktreeResult.stdout.split(/\r?\n/).filter((line) => line.startsWith('worktree ')).length - 1);
  else diagnostic(out, 'GIT_WORKTREES_UNKNOWN', 'UNKNOWN', '.git', 'Git worktrees could not be read.');
  const statusResult = git(realRoot, ['status', '--porcelain', '--untracked-files=all']);
  if (statusResult.ok) out.uncommitted = statusResult.stdout.split(/\r?\n/).filter(Boolean).length;
  else diagnostic(out, 'GIT_STATUS_UNKNOWN', 'UNKNOWN', '.git/index', 'Git working-tree state could not be read.');
  const headProbe = git(realRoot, ['rev-parse', '--verify', 'HEAD']);
  if (!headProbe.ok) diagnostic(out, 'GIT_HEAD_UNKNOWN', 'UNKNOWN', '.git/HEAD', 'Git HEAD does not resolve to a commit.');

  if (out.actor) {
    const rel = `docs/handoff/${out.actor}.md`;
    let text = null;
    try { text = readRegular(realRoot, rel); }
    catch (error) { diagnostic(out, 'HANDOFF_UNREADABLE', 'UNKNOWN', rel, error.message); }
    if (text !== null) {
      const base = text.match(/^BASE_COMMIT:\s*([0-9a-f]{7,64})/m)?.[1] ?? null;
      const headResult = git(realRoot, ['rev-parse', 'HEAD']);
      const head = headResult.ok ? chomp(headResult.stdout) : null;
      let current = Boolean(base && head && head.startsWith(base));
      if (!current && base && head) {
        const changed = git(realRoot, ['diff', '--name-only', base, 'HEAD', '--']);
        if (changed.ok) current = changed.stdout.split(/\r?\n/).filter(Boolean).every((item) => item === rel);
        else diagnostic(out, 'HANDOFF_FRESHNESS_UNKNOWN', 'UNKNOWN', rel, 'The handoff base commit could not be compared with HEAD.');
      }
      if (!base) diagnostic(out, 'HANDOFF_BASE_MISSING', 'DRIFT', rel, 'Handoff has no valid BASE_COMMIT.');
      if (!head) diagnostic(out, 'GIT_HEAD_UNKNOWN', 'UNKNOWN', '.git/HEAD', 'Git HEAD could not be read.');
      out.handoff = { path: rel, current };
    }
  }

  try {
    const index = readRegular(realRoot, 'docs/wiki/index.md');
    if (index !== null) out.wiki_entries = index.split(/\r?\n/).filter((line) => line.startsWith('- ')).length;
  } catch (error) { diagnostic(out, 'WIKI_UNREADABLE', 'UNKNOWN', 'docs/wiki/index.md', error.message); }

  const sprints = [...new Set(storySlots.map(({ id }) => Number(id.match(/^S(\d+)-/)[1])))].sort((a, b) => a - b);
  const retroSkipped = out.plan?.scale === 'tiny' || out.plan?.scale === 'small';
  for (const sprint of sprints) {
    const entries = storySlots.filter(({ id }) => Number(id.match(/^S(\d+)-/)[1]) === sprint);
    const complete = entries.every(({ document }) => document?.execution?.status === 'merged');
    if (!complete || retroSkipped) continue;
    const rel = `docs/retros/sprint-${sprint}.md`;
    if (!regularExists(out, realRoot, rel, 'RETRO_UNREADABLE')) out.sprints_without_retro.push(sprint);
  }

  const hasSpec = regularExists(out, realRoot, 'docs/spec.md', 'SPEC_UNREADABLE');
  const hasPlan = planText !== null;
  const approvalStops = !out.approval || out.approval.status !== 'approved' || out.approval.plan_changed;
  if (approvalStops) out.phase = hasSpec || hasPlan || storySlots.length ? 'planning' : 'discovery';
  else if (out.sprints_without_retro.length) out.phase = 'retrospective';
  else if (storySlots.length) out.phase = out.unmerged.length ? 'implementation' : 'done';
  else if (!hasSpec && !hasPlan) out.phase = 'discovery';
  else if (!hasPlan) out.phase = 'specification';
  else out.phase = 'decomposition';

  const completionUncertain = out.diagnostics.some((item) => item.status === 'UNKNOWN' && [
    'PLAN_UNREADABLE', 'PLAN_POLICY_INVALID', 'STORIES_UNREADABLE', 'STORY_UNREADABLE',
    'RETRO_UNREADABLE', 'GIT_TRACKING_UNKNOWN', 'GIT_BRANCH_UNKNOWN', 'GIT_WORKTREES_UNKNOWN',
    'GIT_STATUS_UNKNOWN', 'GIT_HEAD_UNKNOWN',
  ].includes(item.code)) || out.diagnostics.some((item) => item.code === 'PLAN_POLICY_INVALID');
  if (out.phase === 'done' && !out.approval?.implementation_ready) out.phase = 'planning';
  if (out.phase === 'done' && completionUncertain) {
    out.phase = out.diagnostics.some((item) => item.code === 'PLAN_POLICY_INVALID') ? 'planning' : 'implementation';
  }
  out.next_reference = PHASES[out.phase];
  out.current_sprint = out.sprints_without_retro[0]
    ?? (out.unmerged.length ? Math.min(...out.unmerged.map((id) => Number(id.match(/^S(\d+)-/)[1]))) : null)
    ?? (sprints.length ? sprints.at(-1) : null);
  if (out.plan) {
    out.plan.tracked = planTracked;
    out.plan.blob_digest = digestNow;
  }
  return out;
}

import fs from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { DeliverError, canonical, internalDirectory, readRun } from './state.mjs';
import { inspectProjectState, readApprovalMarker, readPlanPolicy } from './project-state.mjs';
import { isValidGitBranchName, parseStory, readStory, replaceStoryExecution, storyTaskContract } from './story.mjs';

const APPROVAL = 'docs/approval.json';
const PLAN = 'docs/plan.md';
const JOURNAL = '.deliver/current-pm-transaction.json';
const TRANSITION_JOURNAL = '.deliver/transition-transaction.json';
const MAX_BYTES = 8 * 1024 * 1024;
const record = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const fail = (message) => { throw new DeliverError(message, 66); };
const json = (value) => `${JSON.stringify(value, null, 2)}\n`;
const stamp = () => new Date().toISOString().replace('T', ' ').replace('Z', '').slice(0, 16);

function safeText(value, label, max = 1000) {
  if (typeof value !== 'string' || !value.trim() || value.length > max || /[\x00-\x1f\x7f]/.test(value)) fail(`invalid ${label}`);
  return value;
}

function secretScan(text) {
  if (/-----BEGIN [A-Z ]*PRIVATE KEY|gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{22,}|AKIA[0-9A-Z]{16}|sk-[A-Za-z0-9_-]{20,}|xox[baprs]-[A-Za-z0-9-]{10,}|AIza[0-9A-Za-z_-]{35}|eyJ[A-Za-z0-9_-]{17,}\.eyJ[A-Za-z0-9_-]{10,}/.test(text)
    || /(?:api[_-]?key|secret|token|passw(?:or)?d|credential)["']?\s*[:=]\s*["'][A-Za-z0-9_/+=.-]{8,}["']/i.test(text)
    || /(?:api[_-]?key|secret|token|passw(?:or)?d|credential)\s*[:=]\s*[A-Za-z0-9_/+=.-]{8,}/i.test(text)) fail('secret-shaped content cannot be written to tracked project records');
}

function rootPath(root) {
  try {
    const stat = fs.lstatSync(root);
    if (!stat.isDirectory() || stat.isSymbolicLink()) fail('project root must be a real directory');
    return fs.realpathSync.native(root);
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    fail(`cannot access project root: ${error.message}`);
  }
}

function safeRel(rel) {
  if (typeof rel !== 'string' || path.isAbsolute(rel) || /[\x00-\x1f\x7f]/.test(rel)) fail('unsafe current project path');
  const parts = rel.split(/[\\/]/);
  if (!parts.length || parts.some((part) => !part || part === '.' || part === '..')) fail('unsafe current project path');
  const normalized = parts.join('/');
  if (normalized !== APPROVAL && normalized !== JOURNAL && !/^docs\/stories\/S\d+-\d+-[^/]+\.md$/.test(normalized)) fail('current project write is outside the transaction contract');
  return normalized;
}

function checkedPath(root, rel, { createParents = false } = {}) {
  const realRoot = rootPath(root);
  const normalized = safeRel(rel);
  const parts = normalized.split('/');
  let cursor = realRoot;
  for (let index = 0; index < parts.length; index++) {
    cursor = path.join(cursor, parts[index]);
    try {
      const stat = fs.lstatSync(cursor);
      if (stat.isSymbolicLink()) fail(`current project path is a symlink: ${normalized}`);
      if (index < parts.length - 1 && !stat.isDirectory()) fail(`current project parent is not a directory: ${normalized}`);
    } catch (error) {
      if (error instanceof DeliverError) throw error;
      if (error.code !== 'ENOENT') throw error;
      if (!createParents || index === parts.length - 1) break;
      fs.mkdirSync(cursor, { mode: 0o700 });
    }
  }
  return path.join(realRoot, ...parts);
}

function read(root, rel) {
  const file = checkedPath(root, rel);
  try {
    const stat = fs.lstatSync(file);
    if (!stat.isFile() || stat.isSymbolicLink() || stat.size > MAX_BYTES) fail(`invalid current project file: ${rel}`);
    return fs.readFileSync(file, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

function parseJson(text, label) {
  let value;
  try { value = JSON.parse(text); } catch { fail(`invalid JSON in ${label}`); }
  if (!record(value)) fail(`${label} must contain a JSON object`);
  return value;
}

function atomic(root, rel, content) {
  const file = checkedPath(root, rel, { createParents: true });
  const temp = `${file}.${process.pid}.${randomUUID()}.tmp`;
  const fd = fs.openSync(temp, 'wx', 0o600);
  try { fs.writeFileSync(fd, content); fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
  try { fs.renameSync(temp, file); } finally { try { fs.unlinkSync(temp); } catch {} }
}

function git(root, args) {
  try {
    return execFileSync('git', ['-C', root, ...args], {
      encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 10000, windowsHide: true,
    }).replace(/(\r?\n)+$/, '');
  } catch (error) {
    fail(`Git cannot verify current project state: ${String(error.stderr || error.message).trim()}`);
  }
}

function tracked(root, rel) {
  try {
    execFileSync('git', ['-C', root, 'ls-files', '--error-unmatch', '--', rel], {
      stdio: ['ignore', 'ignore', 'ignore'], timeout: 10000, windowsHide: true,
    });
    return true;
  } catch { return false; }
}

function ignored(root, rel) {
  try {
    execFileSync('git', ['-C', root, 'check-ignore', '--no-index', '-q', '--', rel], {
      stdio: ['ignore', 'ignore', 'ignore'], timeout: 10000, windowsHide: true,
    });
    return true;
  } catch (error) {
    if (error.status === 1) return false;
    fail(`Git cannot check ignore rules for ${rel}`);
  }
}

function cksum(text) {
  const bytes = Buffer.from(text);
  let crc = 0;
  const add = (byte) => {
    crc = (crc ^ (byte << 24)) >>> 0;
    for (let bit = 0; bit < 8; bit++) crc = ((crc << 1) ^ (crc & 0x80000000 ? 0x04c11db7 : 0)) >>> 0;
  };
  for (const byte of bytes) add(byte);
  for (let size = bytes.length; size > 0; size = Math.floor(size / 256)) add(size & 255);
  return (~crc >>> 0).toString(16).padStart(8, '0');
}

export function currentActorId(root) {
  let identity = '';
  for (const key of ['user.email', 'user.name']) {
    try { identity = git(root, ['config', key]); } catch {}
    if (identity) break;
  }
  identity = identity.replace(/[A-Z]/g, (letter) => letter.toLowerCase());
  const slug = identity.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  if (!slug) fail('Git identity is required for current project claims');
  return `${slug}-${(cksum(identity) + cksum(`${identity}:pm-skill`)).slice(0, 12)}`;
}

function withLock(root, callback) {
  const dir = internalDirectory(root, []);
  const lock = path.join(dir, 'current-pm.lock');
  let fd;
  try { fd = fs.openSync(lock, 'wx', 0o600); }
  catch (error) {
    if (error.code === 'EEXIST') fail('current project records are locked; inspect the owner before recovery');
    throw error;
  }
  fs.writeFileSync(fd, `${process.pid}\n`);
  try { return callback(); }
  finally { fs.closeSync(fd); try { fs.unlinkSync(lock); } catch {} }
}

function validateJournal(journal) {
  if (!record(journal) || journal.format !== 'current' || !Array.isArray(journal.writes) || journal.writes.length > 2) fail('invalid current project recovery journal');
  if (new Set(journal.writes.map((item) => item.path)).size !== journal.writes.length) fail('duplicate current project journal path');
  for (const item of journal.writes) {
    safeRel(item.path);
    if (item.path === JOURNAL || !(item.before === null || typeof item.before === 'string') || typeof item.after !== 'string') fail('unsafe current project recovery journal');
    secretScan(item.after);
  }
  return journal;
}

function applyJournal(root, journal) {
  validateJournal(journal);
  for (const item of journal.writes) {
    const current = read(root, item.path);
    if (current !== item.before && current !== item.after) fail(`current project transaction conflict at ${item.path}; preserve and reconcile both versions`);
  }
  for (const item of journal.writes) {
    if (read(root, item.path) === item.after) continue;
    atomic(root, item.path, item.after);
  }
}

export function assertCurrentPmReady(root) {
  if (read(root, JOURNAL) !== null) fail('interrupted current project transaction; run pm.mjs recover before continuing');
  let transition;
  try { transition = fs.lstatSync(path.join(rootPath(root), TRANSITION_JOURNAL)); }
  catch (error) { if (error.code !== 'ENOENT') throw error; }
  if (transition) {
    if (!transition.isFile() || transition.isSymbolicLink()) fail('invalid Execution transition journal');
    fail('interrupted Execution transition; run pm.mjs recover before continuing');
  }
}

function transact(root, makeWrites) {
  return withLock(root, () => {
    assertCurrentPmReady(root);
    const pending = new Map();
    const get = (rel) => {
      const normalized = safeRel(rel);
      if (normalized === JOURNAL) fail('journal cannot be a transaction target');
      if (!pending.has(normalized)) pending.set(normalized, { path: normalized, before: read(root, normalized) });
      return pending.get(normalized).before;
    };
    const set = (rel, content) => {
      const normalized = safeRel(rel);
      get(normalized);
      secretScan(content);
      pending.get(normalized).after = content;
    };
    const result = makeWrites(get, set);
    const writes = [...pending.values()].filter((item) => item.after !== undefined && item.after !== item.before);
    if (!writes.length) return result;
    for (const item of writes) if (ignored(root, item.path)) fail(`current project record is ignored by Git: ${item.path}`);
    for (const item of pending.values()) if (read(root, item.path) !== item.before) fail(`current project records changed concurrently: ${item.path}`);
    const journal = { format: 'current', writes };
    atomic(root, JOURNAL, json(journal));
    applyJournal(root, journal);
    fs.unlinkSync(checkedPath(root, JOURNAL));
    return result;
  });
}

export function recoverCurrentPm(root) {
  return withLock(root, () => {
    const raw = read(root, JOURNAL);
    if (raw === null) return { recovered: false };
    applyJournal(root, parseJson(raw, 'current project journal'));
    fs.unlinkSync(checkedPath(root, JOURNAL));
    return { recovered: true };
  });
}

export function initializeCurrentPm(root, name = path.basename(root)) {
  safeText(name, 'project name', 200);
  return transact(root, (get, set) => {
    const existing = get(APPROVAL);
    if (existing !== null) {
      readApprovalMarker(root);
      return { format: 'current', approval_path: APPROVAL, status: parseJson(existing, APPROVAL).status };
    }
    const marker = { status: 'pending', approver: null, approved_date: null, plan_digest: null, updated: stamp() };
    set(APPROVAL, json(marker));
    return { format: 'current', approval_path: APPROVAL, status: 'pending' };
  });
}

export function approveCurrentPm(root, approver) {
  safeText(approver, 'approver', 256);
  return transact(root, (get, set) => {
    const before = get(APPROVAL);
    if (before === null) fail('current project has no approval marker; run pm.mjs init first');
    const marker = readApprovalMarker(root);
    if (!tracked(root, APPROVAL) || !tracked(root, PLAN)) fail('approval requires tracked docs/approval.json and docs/plan.md files');
    readPlanPolicy(root);
    const plan = path.join(rootPath(root), 'docs', 'plan.md');
    const stat = fs.lstatSync(plan);
    if (!stat.isFile() || stat.isSymbolicLink() || stat.size > MAX_BYTES) fail('approval requires a regular docs/plan.md file');
    const digest = git(root, ['hash-object', '--', PLAN]);
    if (!/^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(digest)) fail('Git returned an invalid plan digest');
    const now = stamp();
    set(APPROVAL, json({ ...marker, status: 'approved', approver, approved_date: now, plan_digest: digest, updated: now }));
    return { format: 'current', status: 'approved', approver, plan_digest: digest };
  });
}

export function revokeCurrentPm(root, reason) {
  if (reason !== undefined) safeText(reason, 'revocation reason', 1000);
  return transact(root, (get, set) => {
    const before = get(APPROVAL);
    if (before === null) fail('current project has no approval marker');
    if (!tracked(root, APPROVAL)) fail('revocation requires tracked docs/approval.json');
    const marker = readApprovalMarker(root);
    const now = stamp();
    set(APPROVAL, json({ ...marker, status: 'revoked', updated: now, ...(reason === undefined ? {} : { reason }) }));
    return { format: 'current', status: 'revoked', ...(reason === undefined ? {} : { reason }) };
  });
}

function requireExecutable(root, actorId) {
  assertCurrentPmReady(root);
  const state = inspectProjectState(root, { actorId });
  if (!state || state.format !== 'current') fail('current project state is unavailable');
  if (!state.approval?.implementation_ready) fail('current project approval is not executable');
  if (!state.plan?.integrationBranch) fail('approved plan needs an Integration branch');
  if (state.unreadable.length || state.diagnostics.some((item) => ['STORIES_UNREADABLE', 'STORY_UNREADABLE'].includes(item.code))) {
    fail('current story inventory is unreadable; reconcile it before claiming or continuing');
  }
  return state;
}

function resolvedBuilder(builder) {
  if (builder === 'expert-builder') fail('story explicitly routes to unavailable expert-builder; obtain an approved routing change');
  if (builder === 'auto' || builder === 'codex-builder') return 'codex-builder';
  fail('story has an unsupported builder route');
}

function targetBranch(document) {
  return `pm/${path.basename(document.path, '.md')}`;
}

function storyRefConflict(root, storyId) {
  const prefix = `pm/${storyId}-`;
  const refs = git(root, ['for-each-ref', '--format=%(refname)', 'refs/heads', 'refs/remotes']).split(/\r?\n/).filter(Boolean);
  const matchingRef = refs.find((ref) => {
    if (ref.startsWith('refs/heads/')) return ref.slice('refs/heads/'.length).startsWith(prefix);
    if (!ref.startsWith('refs/remotes/')) return false;
    const remoteBranch = ref.slice('refs/remotes/'.length).split('/').slice(1).join('/');
    return remoteBranch.startsWith(prefix);
  });
  if (matchingRef) return matchingRef;
  const worktrees = git(root, ['worktree', 'list', '--porcelain']).split(/\r?\n/);
  return worktrees.find((line) => line.startsWith('branch refs/heads/')
    && line.slice('branch refs/heads/'.length).startsWith(prefix)) || null;
}

function requireCleanIntegrationCheckout(root, integrationBranch) {
  const branch = git(root, ['symbolic-ref', '--short', 'HEAD']);
  if (branch !== integrationBranch) fail(`claim preparation requires the plan integration branch ${integrationBranch}`);
  const dirty = git(root, ['status', '--porcelain=v1', '--untracked-files=all']).split(/\r?\n/)
    .filter((line) => line && !line.slice(3).startsWith('.deliver/'));
  if (dirty.length) fail('claim preparation requires a clean integration checkout');
}

export function claimCurrentPm(root, storyPath, plannedBranch) {
  const actor = currentActorId(root);
  assertCurrentPmReady(root);
  const first = readStory(root, storyPath);
  const builder = resolvedBuilder(first.meta.builder);
  const branch = plannedBranch || first.execution?.branch || targetBranch(first);
  if (!isValidGitBranchName(branch)) fail('claim branch is not a valid Git branch name');
  if (!branch.startsWith(`pm/${first.id}-`)) fail(`claim branch must begin with pm/${first.id}-`);
  if (first.execution?.status === 'merged') fail('merged stories cannot be claimed');
  if (first.execution && first.execution.owner !== actor) fail('story is already claimed by another actor');
  if (first.execution && (first.execution.builder !== builder || first.execution.branch !== branch)) {
    fail('existing claim route or branch differs; reconcile it without resetting counters');
  }
  const project = requireExecutable(root, actor);
  if (branch === project.plan.integrationBranch) fail('story claim branch must differ from the integration branch');
  if (first.execution) {
    requireCleanIntegrationCheckout(root, project.plan.integrationBranch);
    return {
      format: 'current', actor, story: first.id, story_path: first.path, builder, branch,
      contract_hash: first.contractHash, execution_hash: first.executionHash, resumed: true,
      rounds: first.execution.rounds, retries: first.execution.retries,
    };
  }
  for (const document of project.stories) {
    const active = document.execution && document.execution.status !== 'merged';
    if (!active || document.id === first.id) continue;
    if (document.execution.owner === actor) fail(`PARALLEL_BATCH_REQUIRED: actor already owns active story ${document.id}`);
    if (document.execution.branch === branch) fail(`claim branch is already owned by story ${document.id}`);
  }
  requireCleanIntegrationCheckout(root, project.plan.integrationBranch);
  const conflict = storyRefConflict(root, first.id);
  if (conflict) fail(`unclaimed story has an existing target branch or worktree: ${conflict}`);
  return transact(root, (get, set) => {
    const before = get(first.path);
    if (before === null) fail(`story is missing: ${first.path}`);
    const document = parseStory(before, first.path);
    if (document.contractHash !== first.contractHash || document.execution !== null) fail('story changed while its claim was being prepared');
    const transition = replaceStoryExecution(document, {
      owner: actor, builder, branch, status: 'claimed', rounds: 0, retries: 0, updated: stamp(),
    });
    set(first.path, transition.after);
    return {
      format: 'current', actor, story: document.id, story_path: document.path, builder, branch,
      contract_hash: transition.contractHash, execution_hash: transition.executionHash, resumed: false,
      rounds: 0, retries: 0,
    };
  });
}

function currentBranch(root) {
  const branch = git(root, ['symbolic-ref', '--short', 'HEAD']);
  if (!isValidGitBranchName(branch)) fail('check out a named valid story branch');
  return branch;
}

function packetMatchesStory(packet, document) {
  const contract = storyTaskContract(document);
  if (packet.id !== contract.id || canonical(packet.acceptance.map((item) => item.text)) !== canonical(contract.acceptanceText)) {
    fail('task must preserve the story ID and every acceptance criterion in order');
  }
  if (!packet.touches.every((touch) => contract.touches.some((scope) => touch === scope || touch.startsWith(`${scope}/`)))) {
    fail('task touches exceed the current story scope');
  }
  if (canonical(packet.specs) !== canonical(contract.specs)) fail('task must preserve every current story spec in order');
  return contract;
}

export function prepareCurrentBinding(state, packet, storyPath) {
  if (!storyPath) fail('current projects require start --story docs/stories/<story>.md');
  const actor = currentActorId(state.project_root);
  const project = requireExecutable(state.project_root, actor);
  const document = readStory(state.project_root, storyPath);
  packetMatchesStory(packet, document);
  const execution = document.execution;
  if (!execution || execution.owner !== actor || execution.builder !== 'codex-builder'
    || !['claimed', 'building'].includes(execution.status)) fail('an active current Codex story claim is required');
  if (execution.branch !== currentBranch(state.project_root)) fail('check out the claimed story branch before starting');
  for (const other of project.stories) {
    if (other.id !== document.id && other.execution?.status !== 'merged' && other.execution?.owner === actor) {
      fail(`PARALLEL_BATCH_REQUIRED: actor already owns active story ${other.id}`);
    }
  }
  const runs = internalDirectory(state.project_root, ['runs']);
  for (const name of fs.readdirSync(runs).filter((name) => /^[0-9a-f-]{36}\.json$/.test(name))) {
    if (name === `${state.run_id}.json`) continue;
    const other = readRun(path.join(runs, name)).state;
    const binding = other.pm_binding;
    if (binding?.format === 'current' && binding.story === document.id) {
      fail('story already has a current Codex run; resume it without resetting counters');
    }
  }
  state.counters.retries = Math.max(state.counters.retries, execution.retries);
  state.counters.fixes = Math.max(state.counters.fixes, execution.rounds);
  if (state.counters.retries > 2 || state.counters.fixes > 3) fail('persisted story retry budget is already exhausted');
  return {
    format: 'current', actor, story: document.id, story_path: document.path,
    contract_hash: document.contractHash, execution_hash: document.executionHash,
    plan_digest: project.approval.plan_digest, branch: execution.branch, builder: execution.builder,
    integration_branch: project.plan.integrationBranch,
  };
}

export function assertCurrentBinding(state, { allowBlocked = false } = {}) {
  const binding = state.pm_binding;
  if (!binding || binding.format !== 'current') fail('run has no current project binding');
  const actor = currentActorId(state.project_root);
  if (actor !== binding.actor) fail('current project actor identity changed');
  const project = requireExecutable(state.project_root, actor);
  if (project.approval.plan_digest !== binding.plan_digest || project.plan.integrationBranch !== binding.integration_branch) {
    fail('current project plan approval or integration branch changed');
  }
  const document = readStory(state.project_root, binding.story_path);
  const execution = document.execution;
  if (document.id !== binding.story || document.contractHash !== binding.contract_hash || document.executionHash !== binding.execution_hash) {
    fail('current story contract or execution claim changed; reconcile before continuing');
  }
  const allowedStatuses = allowBlocked
    ? ['claimed', 'building', 'built', 'in-review', 'blocked']
    : ['claimed', 'building', 'built', 'in-review'];
  if (!execution || execution.owner !== binding.actor || execution.builder !== binding.builder
    || execution.branch !== binding.branch || !allowedStatuses.includes(execution.status)) {
    fail('current story ownership, route, branch or status changed');
  }
  if (currentBranch(state.project_root) !== binding.branch) fail('checked-out branch differs from the current story claim');
  if (state.plan.path !== path.join(rootPath(state.project_root), 'docs', 'plan.md')) fail('runtime plan is not the approved shared plan');
  if (state.task) packetMatchesStory(state.task.packet, document);
  return binding;
}

import fs from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import {
  archiveEvidence,
  canonical,
  DeliverError,
  internalDirectory,
  readRun,
  sha256,
  updateRun,
  validateRunState,
} from './state.mjs';
import { assertPmBinding } from './pm.mjs';
import { parseStory, readStory, replaceStoryExecution } from './story.mjs';
import { captureGitAnchor, inspectScope, legacyAnchorUpgradeSafe, snapshot } from './scope.mjs';

const JOURNAL = '.deliver/transition-transaction.json';
const ACTIVE_STATUSES = new Set(['claimed', 'building', 'built', 'in-review', 'blocked']);
const COMMITTABLE_STATUSES = new Set(['claimed', 'building', 'built', 'in-review']);
const OID = /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/;
const fail = (message, code = 66) => { throw new DeliverError(message, code); };
const json = (value) => `${JSON.stringify(value, null, 2)}\n`;
const now = () => new Date().toISOString();
const stamp = () => now().replace('T', ' ').replace('Z', '').slice(0, 16);
const covers = (scope, rel) => rel === scope || rel.startsWith(`${scope}/`);

function git(root, args, { env = {} } = {}) {
  try {
    return execFileSync('git', ['-C', root, ...args], {
      encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 10000,
      windowsHide: true, env: { ...process.env, ...env },
    }).replace(/(\r?\n)+$/, '');
  } catch (error) {
    fail(`Git cannot complete coordinator transition: ${String(error.stderr || error.message).trim()}`);
  }
}

function gitSucceeds(root, args) {
  try {
    execFileSync('git', ['-C', root, ...args], { stdio: 'ignore', timeout: 10000, windowsHide: true });
    return true;
  } catch { return false; }
}

function rootPath(root) {
  const real = fs.realpathSync(root);
  const stat = fs.lstatSync(real);
  if (!stat.isDirectory() || stat.isSymbolicLink()) fail('project root must be a real directory');
  return real;
}

function safeRel(rel) {
  if (typeof rel !== 'string' || !rel || path.isAbsolute(rel) || /[\x00-\x1f\x7f]/.test(rel)) fail('unsafe transition path');
  const parts = rel.split(/[\\/]/);
  if (parts.some((part) => !part || part === '.' || part === '..')) fail('unsafe transition path');
  const normalized = parts.join('/');
  if (normalized === JOURNAL || /^docs\/stories\/S\d+-\d+-[^/]+\.md$/.test(normalized)
    || /^\.deliver\/runs\/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.json$/.test(normalized)) return normalized;
  fail('transition path is outside the journal contract');
}

function checkedPath(root, rel) {
  const realRoot = rootPath(root);
  const normalized = safeRel(rel);
  let cursor = realRoot;
  for (const part of normalized.split('/')) {
    cursor = path.join(cursor, part);
    try { if (fs.lstatSync(cursor).isSymbolicLink()) fail(`transition path is a symlink: ${normalized}`); }
    catch (error) { if (error.code !== 'ENOENT') throw error; }
  }
  return path.join(realRoot, ...normalized.split('/'));
}

function readText(root, rel) {
  const file = checkedPath(root, rel);
  try {
    const stat = fs.lstatSync(file);
    if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 8 * 1024 * 1024) fail(`invalid transition file: ${rel}`);
    return fs.readFileSync(file, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

function atomic(root, rel, content) {
  const file = checkedPath(root, rel);
  const temp = `${file}.${process.pid}.${randomUUID()}.tmp`;
  let mode = 0o600;
  try { mode = fs.lstatSync(file).mode & 0o777; } catch (error) { if (error.code !== 'ENOENT') throw error; }
  const fd = fs.openSync(temp, 'wx', mode);
  try { fs.writeFileSync(fd, content); fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
  try {
    fs.renameSync(temp, file);
    let directory;
    try {
      directory = fs.openSync(path.dirname(file), 'r');
      fs.fsyncSync(directory);
    } catch (error) {
      if (process.platform !== 'win32') throw error;
    } finally { if (directory !== undefined) fs.closeSync(directory); }
  }
  finally { try { fs.unlinkSync(temp); } catch {} }
}

function removeJournal(root) {
  const file = checkedPath(root, JOURNAL);
  fs.unlinkSync(file);
  let directory;
  try {
    directory = fs.openSync(path.dirname(file), 'r');
    fs.fsyncSync(directory);
  } catch (error) {
    if (process.platform !== 'win32') throw error;
  } finally { if (directory !== undefined) fs.closeSync(directory); }
}

function transitionLocks(root, runFile, callback) {
  const dir = internalDirectory(root, []);
  const locks = [path.join(dir, 'transition.lock'), `${runFile}.lock`];
  const fds = [];
  try {
    for (const lock of locks) {
      try { fds.push([fs.openSync(lock, 'wx', 0o600), lock]); }
      catch (error) {
        if (error.code === 'EEXIST') fail(`transition is locked by another process: ${lock}`);
        throw error;
      }
    }
    for (const [fd] of fds) fs.writeFileSync(fd, `${process.pid} ${now()}\n`);
    return callback();
  } finally {
    for (const [fd, lock] of fds.reverse()) {
      try { fs.closeSync(fd); } finally { try { fs.unlinkSync(lock); } catch {} }
    }
  }
}

function validateJournalShape(journal) {
  if (!journal || typeof journal !== 'object' || Array.isArray(journal) || journal.kind !== 'execution-transition-v1'
    || canonical(Object.keys(journal).sort()) !== canonical(['branch', 'contract_hash', 'kind', 'owner', 'writes'])
    || typeof journal.contract_hash !== 'string' || typeof journal.owner !== 'string' || typeof journal.branch !== 'string'
    || !Array.isArray(journal.writes) || journal.writes.length !== 2) fail('invalid Execution transition journal');
  const paths = journal.writes.map((item) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)
      || canonical(Object.keys(item).sort()) !== canonical(['after', 'before', 'path'])) fail('invalid Execution transition write');
    const normalized = safeRel(item.path);
    if (normalized !== item.path) fail('transition journal paths must use canonical separators');
    return normalized;
  });
  if (new Set(paths).size !== paths.length || !paths.some((item) => item.startsWith('docs/stories/'))
    || !paths.some((item) => item.startsWith('.deliver/runs/'))) fail('invalid Execution transition journal paths');
  for (const item of journal.writes) {
    if (typeof item.before !== 'string' || typeof item.after !== 'string') fail('invalid Execution transition before/after image');
  }
  return journal;
}

function applyJournal(root, journal) {
  validateTransitionJournal(root, journal);
  for (const item of journal.writes) {
    const current = readText(root, item.path);
    if (current !== item.before && current !== item.after) {
      fail(`Execution transition conflict at ${item.path}; preserve changed contracts and reconcile maximum spent counters`);
    }
  }
  for (const item of journal.writes) {
    if (readText(root, item.path) !== item.after) atomic(root, item.path, item.after);
  }
}

export function recoverExecutionTransition(root) {
  root = rootPath(root);
  const raw = readText(root, JOURNAL);
  if (raw === null) return { recovered: false };
  let journal;
  try { journal = JSON.parse(raw); } catch { fail('invalid JSON in Execution transition journal'); }
  const runRel = validateJournalShape(journal).writes.find((item) => item.path.startsWith('.deliver/runs/')).path;
  return transitionLocks(root, checkedPath(root, runRel), () => {
    applyJournal(root, journal);
    removeJournal(root);
    return { recovered: true, run: runRel };
  });
}

function transitionRule(from, to, attempt, reason) {
  if (!ACTIVE_STATUSES.has(from)) fail(`Execution status ${from} cannot transition before integration reconciliation`);
  if (!ACTIVE_STATUSES.has(to)) fail('T05 integration is the only operation allowed to record merged');
  if (from === to && attempt === undefined) return { noop: true };
  if (to === 'blocked') {
    if (attempt !== undefined) fail('blocked transition cannot spend a fix or retry attempt');
    if (!reason) fail('blocked transition requires --reason');
    return { noop: false };
  }
  if (attempt !== undefined) {
    if (to !== 'building' || !['fix', 'retry'].includes(attempt)) fail('fix/retry transitions must return Execution to building');
    return { noop: false };
  }
  const forward = from === 'claimed' && to === 'building'
    || from === 'building' && to === 'built'
    || from === 'built' && to === 'in-review';
  if (!forward) fail(`illegal Execution transition ${from} -> ${to}`);
  return { noop: false };
}

function storyMode(state, document) {
  const expectedEntry = state.execution_audit?.current_entry
    ?? state.baseline?.snapshot?.entries?.[document.path];
  const match = /^file:(644|755):[0-9a-f]{64}$/.exec(expectedEntry || '');
  if (!match) fail('run baseline cannot prove the story file mode');
  const actualEntry = `file:${match[1]}:${sha256(document.text)}`;
  if (actualEntry !== expectedEntry) fail('run audit does not match the before-story image');
  return match[1];
}

function buildExecutionTransition(state, document, {
  to, attempt, reason, transitionAt, evidenceAt, updatedAt,
}) {
  const binding = state.pm_binding;
  const execution = document.execution;
  if (state.phase !== 'active' || binding?.format !== 'current' || !execution
    || binding.story !== document.id || binding.story_path !== document.path
    || binding.contract_hash !== document.contractHash || binding.execution_hash !== document.executionHash
    || binding.actor !== execution.owner || binding.builder !== execution.builder || binding.branch !== execution.branch) {
    fail('before story and run binding do not describe the same active Execution');
  }
  if (typeof transitionAt !== 'string' || !/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(transitionAt)
    || typeof updatedAt !== 'string' || Number.isNaN(Date.parse(updatedAt))) fail('invalid recorded transition timestamps');
  if (reason !== undefined && (typeof reason !== 'string' || !reason.trim() || reason.length > 1000
    || /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(reason))) fail('invalid recorded transition reason');
  const rule = transitionRule(execution.status, to, attempt, reason);
  const maxRetries = Math.max(execution.retries, state.counters.retries);
  const maxFixes = Math.max(execution.rounds, state.counters.fixes);
  if (rule.noop && maxRetries === execution.retries && maxFixes === execution.rounds) {
    return { noop: true, state, execution, document };
  }
  let retries = maxRetries;
  let rounds = maxFixes;
  if (attempt === 'retry') {
    if (retries >= 2) fail('retry limit of 2 has been reached');
    retries += 1;
  }
  if (attempt === 'fix') {
    if (rounds >= 3) fail('fix limit of 3 has been reached');
    rounds += 1;
  }
  const mode = storyMode(state, document);
  const transition = replaceStoryExecution(document, {
    status: to, retries, rounds, updated: transitionAt,
  }, { note: reason ? `${transitionAt} ${attempt || to}: ${reason}` : undefined });
  const next = structuredClone(state);
  next.pm_binding.execution_hash = transition.executionHash;
  next.counters.retries = retries;
  next.counters.fixes = rounds;
  const hasEvidence = next.gates.length > 0 || next.review !== null || next.verification !== null;
  if (hasEvidence && (typeof evidenceAt !== 'string' || Number.isNaN(Date.parse(evidenceAt)))) {
    fail('invalid recorded evidence archive timestamp');
  }
  archiveEvidence(next, 'execution_transition', {
    story: document.id,
    from: execution.status,
    to,
    attempt: attempt ?? null,
    transition_reason: reason ?? null,
  }, evidenceAt || updatedAt);
  const beforeEntry = `file:${mode}:${sha256(transition.before)}`;
  const afterEntry = `file:${mode}:${sha256(transition.after)}`;
  const receipt = {
    from: execution.status,
    to,
    attempt: attempt ?? null,
    reason: reason ?? null,
    before_hash: document.executionHash,
    after_hash: transition.executionHash,
    at: transitionAt,
  };
  if (next.execution_audit) {
    if (next.execution_audit.story_path !== document.path || next.execution_audit.contract_hash !== document.contractHash
      || next.execution_audit.current_entry !== beforeEntry) fail('existing Execution audit does not match the current story');
    next.execution_audit.current_entry = afterEntry;
    next.execution_audit.transitions.push(receipt);
  } else {
    next.execution_audit = {
      story_path: document.path,
      contract_hash: document.contractHash,
      original_entry: next.baseline.snapshot.entries[document.path] ?? null,
      current_entry: afterEntry,
      transitions: [receipt],
    };
  }
  next.events.push({ at: transitionAt, type: 'execution_transition', story: document.id, ...receipt });
  next.revision += 1;
  next.updated_at = updatedAt;
  validateRunState(next);
  return { noop: false, state: next, execution: transition.document.execution, document: transition.document, transition, receipt };
}

function parseRunImage(text, label) {
  let state;
  try { state = JSON.parse(text); } catch { fail(`invalid JSON in ${label}`); }
  return validateRunState(state);
}

function validateTransitionJournal(root, journal) {
  validateJournalShape(journal);
  const storyWrite = journal.writes.find((item) => item.path.startsWith('docs/stories/'));
  const runWrite = journal.writes.find((item) => item.path.startsWith('.deliver/runs/'));
  let beforeDocument;
  let afterDocument;
  try {
    beforeDocument = parseStory(storyWrite.before, storyWrite.path);
    afterDocument = parseStory(storyWrite.after, storyWrite.path);
  } catch (error) { fail(`invalid story image in Execution transition journal: ${error.message}`); }
  const beforeState = parseRunImage(runWrite.before, 'before-run transition image');
  const afterState = parseRunImage(runWrite.after, 'after-run transition image');
  if (beforeState.project_root !== root || afterState.project_root !== root
    || runWrite.path !== `.deliver/runs/${beforeState.run_id}.json`
    || beforeState.run_id !== afterState.run_id) fail('transition journal run identity or root changed');
  const beforeExecution = beforeDocument.execution;
  if (!beforeExecution || journal.contract_hash !== beforeDocument.contractHash
    || afterDocument.contractHash !== beforeDocument.contractHash
    || journal.owner !== beforeExecution.owner || journal.branch !== beforeExecution.branch) {
    fail('transition journal contract, owner or branch does not match its before-story image');
  }
  const receipt = afterState.execution_audit?.transitions?.at(-1);
  if (!receipt) fail('transition journal after-run image has no transition receipt');
  const hadEvidence = beforeState.gates.length > 0 || beforeState.review !== null || beforeState.verification !== null;
  const evidenceAt = hadEvidence
    ? afterState.evidence_history?.[beforeState.evidence_history?.length || 0]?.at
    : afterState.updated_at;
  const generated = buildExecutionTransition(beforeState, beforeDocument, {
    to: receipt.to,
    attempt: receipt.attempt ?? undefined,
    reason: receipt.reason ?? undefined,
    transitionAt: receipt.at,
    evidenceAt,
    updatedAt: afterState.updated_at,
  });
  if (generated.noop || generated.transition.after !== storyWrite.after || json(generated.state) !== runWrite.after) {
    fail('transition journal after images are not the exact legal result of its before images');
  }
  return { storyWrite, runWrite, beforeState, afterState, beforeDocument, afterDocument };
}

export function transitionCurrentExecution(runArg, { to, attempt, reason, expectedRevision } = {}, cwd = process.cwd()) {
  if (typeof to !== 'string') fail('--to is required', 64);
  if (attempt !== undefined && !['fix', 'retry'].includes(attempt)) fail('--attempt must be fix or retry', 64);
  if (reason !== undefined && (typeof reason !== 'string' || !reason.trim() || reason.length > 1000 || /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(reason))) {
    fail('--reason must be printable and at most 1000 characters', 64);
  }
  const initial = readRun(runArg, cwd);
  const root = initial.state.project_root;
  const runRel = `.deliver/runs/${initial.state.run_id}.json`;
  return transitionLocks(root, initial.file, () => {
    if (readText(root, JOURNAL) !== null) fail('interrupted Execution transition; run pm.mjs recover before continuing');
    const loaded = readRun(initial.file, root);
    const state = loaded.state;
    if (expectedRevision !== undefined && state.revision !== expectedRevision) fail(`revision conflict: expected ${expectedRevision}, found ${state.revision}`);
    if (state.phase !== 'active' || state.pm_binding?.format !== 'current') fail('Execution transitions require an active current-bound run');
    assertPmBinding(state, { allowBlocked: true });
    const document = readStory(root, state.pm_binding.story_path);
    const execution = document.execution;
    const built = buildExecutionTransition(state, document, {
      to,
      attempt,
      reason,
      transitionAt: stamp(),
      evidenceAt: now(),
      updatedAt: now(),
    });
    if (built.noop) return { state, file: loaded.file, execution, noop: true };
    const { state: next, transition } = built;
    const runBefore = readText(root, runRel);
    const runAfter = json(next);
    const journal = {
      kind: 'execution-transition-v1',
      contract_hash: document.contractHash,
      owner: execution.owner,
      branch: execution.branch,
      writes: [
        { path: document.path, before: transition.before, after: transition.after },
        { path: runRel, before: runBefore, after: runAfter },
      ],
    };
    atomic(root, JOURNAL, json(journal));
    applyJournal(root, journal);
    removeJournal(root);
    return { state: next, file: loaded.file, execution: transition.document.execution, noop: false };
  });
}

function statusPaths(root) {
  const records = git(root, ['status', '--porcelain=v1', '-z', '--untracked-files=all']).split('\0').filter(Boolean);
  const paths = [];
  for (let index = 0; index < records.length; index++) {
    const item = records[index];
    if (item.length < 4) continue;
    const status = item.slice(0, 2);
    paths.push(item.slice(3));
    if ((status[0] === 'R' || status[0] === 'C') && records[index + 1]) paths.push(records[++index]);
  }
  return [...new Set(paths.filter((item) => !item.startsWith('.deliver/')))].sort();
}

function indexFlags(root, env = {}) {
  return git(root, ['ls-files', '-v', '-z'], { env });
}

function indexFlagRecords(root) {
  const records = new Map();
  for (const record of indexFlags(root).split('\0').filter(Boolean)) {
    if (record.length < 3 || record[1] !== ' ') fail('cannot parse Git index flags');
    records.set(record.slice(2), record[0]);
  }
  return records;
}

function gitlinkPaths(root) {
  return git(root, ['ls-files', '--stage', '-z']).split('\0').filter(Boolean).flatMap((record) => {
    const match = /^160000 [0-9a-f]+ [0-3]\t(.+)$/.exec(record);
    return match ? [match[1]] : [];
  });
}

function anchorProtectionHash(anchor) {
  return sha256(canonical({
    protected_hash: anchor.protected_hash,
    submodules: anchor.submodules || {},
  }));
}

function expectedIndex(root, parent, paths) {
  const dir = internalDirectory(root, ['tmp']);
  const index = path.join(dir, `commit-index-${randomUUID()}`);
  const env = { GIT_INDEX_FILE: index };
  try {
    const records = indexFlagRecords(root);
    for (const rel of paths) {
      const tag = records.get(rel);
      if (tag !== undefined && tag !== 'H') {
        fail(`commit preparation rejects unsupported index flag ${tag} on intended path: ${rel}`, 74);
      }
    }
    git(root, ['read-tree', parent], { env });
    for (const [rel, tag] of records) {
      const upper = tag.toUpperCase();
      if (upper === 'S') git(root, ['update-index', '--skip-worktree', '--', rel], { env });
      if (tag !== upper) git(root, ['update-index', '--assume-unchanged', '--', rel], { env });
    }
    git(root, ['add', '-A', '--', ...paths], { env });
    return {
      tree: git(root, ['write-tree'], { env }),
      index_flags: sha256(indexFlags(root, env)),
    };
  } finally { try { fs.unlinkSync(index); } catch {} }
}

function treeFingerprint(root, tree, rel) {
  const record = git(root, ['ls-tree', '-z', tree, '--', rel]).split('\0').filter(Boolean)
    .find((item) => item.endsWith(`\t${rel}`));
  if (!record) return null;
  const match = /^(100644|100755|120000) blob ([0-9a-f]+)\t/.exec(record);
  if (!match) fail(`prepared tree contains unsupported entry for audited path: ${rel}`, 74);
  let content;
  try {
    content = execFileSync('git', ['-C', root, 'cat-file', 'blob', match[2]], {
      stdio: ['ignore', 'pipe', 'pipe'], timeout: 10000, windowsHide: true,
    });
  } catch (error) {
    fail(`Git cannot read prepared tree entry ${rel}: ${String(error.stderr || error.message).trim()}`);
  }
  if (match[1] === '120000') return `symlink:${sha256(content)}`;
  return `file:${match[1] === '100755' ? '755' : '644'}:${sha256(content)}`;
}

function assertTreeCoverage(root, tree, paths, entries) {
  for (const rel of paths) {
    if (treeFingerprint(root, tree, rel) !== (entries[rel] ?? null)) {
      fail(`prepared tree does not contain the audited worktree entry: ${rel}`, 74);
    }
  }
}

export function prepareCommitAdoption(runArg, expectedRevision, cwd = process.cwd()) {
  const loaded = readRun(runArg, cwd);
  return updateRun(loaded.file, expectedRevision, (state) => {
    if (state.phase !== 'active' || state.pm_binding?.format !== 'current') fail('commit preparation requires an active current-bound run');
    if (state.commit_adoption?.pending) fail('a commit adoption is already pending');
    assertPmBinding(state);
    if (!COMMITTABLE_STATUSES.has(readStory(state.project_root, state.pm_binding.story_path).execution.status)) {
      fail('current Execution status cannot be committed by T04');
    }
    if (!gitSucceeds(state.project_root, ['diff', '--cached', '--quiet', '--'])) fail('commit preparation requires a clean index');
    const checked = inspectScope(state);
    if (!checked.report.ok) fail('commit preparation requires a passing cumulative scope check', 74);
    const anchor = captureGitAnchor(state.project_root);
    if (!state.git_anchor) {
      if (checked.report.git_metadata_compatibility !== 'legacy-v1') fail('current run has no compatible audited Git anchor');
      if (!legacyAnchorUpgradeSafe(state.project_root)) {
        fail('legacy Git metadata cannot prove the mode or target of an active hook; remove it or start a fresh run', 74);
      }
      state.git_anchor = anchor;
      state.baseline_metadata_version = 'legacy-v1';
      state.events.push({ at: now(), type: 'git_anchor_bootstrapped', head: anchor.head, ref: anchor.ref });
    } else if (canonical(anchor) !== canonical(state.git_anchor)) {
      if (!['flat-v1', 'protected-v1'].includes(checked.report.git_anchor_compatibility)) {
        fail('current Git state differs from the audited anchor');
      }
      state.git_anchor = anchor;
      state.events.push({ at: now(), type: 'git_anchor_upgraded', head: anchor.head, ref: anchor.ref });
    }
    const dirty = statusPaths(state.project_root);
    const storyPath = state.pm_binding.story_path;
    const changed = new Set(checked.report.changed);
    const ignoredChanged = git(state.project_root, ['ls-files', '--others', '--ignored', '--exclude-standard', '-z'])
      .split('\0').filter((rel) => changed.has(rel)
        && state.task.packet.touches.some((scope) => covers(scope, rel)));
    if (ignoredChanged.length) {
      fail(`commit preparation cannot leave audited source outside the commit: ${ignoredChanged.sort().join(', ')}`, 74);
    }
    const nestedChanges = [...changed].filter((rel) => gitlinkPaths(state.project_root)
      .some((module) => rel.startsWith(`${module}/`)));
    if (nestedChanges.length) {
      fail(`commit preparation cannot represent initialized submodule worktree changes: ${nestedChanges.sort().join(', ')}`, 74);
    }
    const intended = [...new Set([
      ...[...changed].filter((rel) => state.task.packet.touches.some((scope) => covers(scope, rel))),
      ...(state.execution_audit?.story_path === storyPath ? [storyPath] : []),
    ])].sort();
    for (const rel of dirty) {
      if (intended.includes(rel)) continue;
      if (state.baseline.dirty_paths.some((original) => covers(original, rel) || covers(rel, original))) continue;
      fail(`commit preparation found an unaudited dirty path: ${rel}`, 74);
    }
    if (!intended.length) fail('commit preparation found no audited changes to commit');
    const expected = expectedIndex(state.project_root, anchor.head, intended);
    assertTreeCoverage(state.project_root, expected.tree, intended, checked.current.entries);
    const pending = {
      token: randomUUID(),
      parent: anchor.head,
      ref: anchor.ref,
      expected_tree: expected.tree,
      expected_index_flags: expected.index_flags,
      content_hash: sha256(canonical(checked.current.entries)),
      protected_hash: anchorProtectionHash(anchor),
      paths: intended,
      prepared_at: now(),
    };
    state.commit_adoption = { pending, history: [...(state.commit_adoption?.history || [])] };
    state.events.push({ at: now(), type: 'commit_prepared', token: pending.token, parent: pending.parent, paths: pending.paths });
    return pending;
  });
}

export function adoptPreparedCommit(runArg, { token, commit, expectedRevision } = {}, cwd = process.cwd()) {
  if (typeof token !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(token)) {
    fail('--token must be the commit preparation token', 64);
  }
  if (typeof commit !== 'string' || !OID.test(commit)) fail('--commit must be a full Git object ID', 64);
  const loaded = readRun(runArg, cwd);
  return updateRun(loaded.file, expectedRevision, (state) => {
    const pending = state.commit_adoption?.pending;
    if (!pending || pending.token !== token) fail('commit preparation token is missing or stale');
    assertPmBinding(state);
    const root = state.project_root;
    const head = git(root, ['rev-parse', '--verify', 'HEAD']);
    if (head !== commit) fail('supplied commit is not the current HEAD');
    const lineage = git(root, ['rev-list', '--parents', '-n', '1', head]).split(/\s+/);
    if (lineage.length !== 2 || lineage[1] !== pending.parent) fail('adopted commit must be one single-parent child of the prepared HEAD');
    const anchor = captureGitAnchor(root);
    if (anchor.ref !== pending.ref) fail('adopted commit is on a different branch');
    if (anchor.tree !== pending.expected_tree || anchor.index_tree !== pending.expected_tree
      || !gitSucceeds(root, ['diff', '--cached', '--quiet', '--'])) fail('adopted commit tree or index differs from the prepared tree');
    if (anchor.index_flags !== pending.expected_index_flags) fail('Git index flags changed after commit preparation');
    if (anchorProtectionHash(anchor) !== pending.protected_hash) fail('protected Git config, hooks, index flags or submodule metadata changed during commit');
    const checked = inspectScope(state, { allowPendingAdoption: true, ignoreGitAnchor: true });
    if (!checked.report.ok || sha256(canonical(checked.current.entries)) !== pending.content_hash) {
      fail('worktree content differs from the prepared audited snapshot', 74);
    }
    const executionStatus = readStory(root, state.pm_binding.story_path).execution.status;
    if (!COMMITTABLE_STATUSES.has(executionStatus)) fail('current Execution status cannot be adopted by T04');
    const receipt = {
      token,
      parent: pending.parent,
      commit: head,
      tree: anchor.tree,
      ref: anchor.ref,
      paths: [...pending.paths],
      execution_status: executionStatus,
      execution_hash: state.pm_binding.execution_hash,
      adopted_at: now(),
    };
    state.git_anchor = anchor;
    state.commit_adoption.pending = null;
    state.commit_adoption.history.push(receipt);
    archiveEvidence(state, 'commit_adopted', { commit: head, parent: pending.parent, paths: [...pending.paths] });
    state.events.push({ at: now(), type: 'commit_adopted', commit: head, parent: pending.parent, paths: pending.paths });
    return receipt;
  });
}

export function assertFinalCandidate(state) {
  if (state.pm_binding?.format !== 'current') return;
  assertPmBinding(state);
  if (state.commit_adoption?.pending) fail('commit adoption is pending; commit or reconcile it before finishing');
  const execution = readStory(state.project_root, state.pm_binding.story_path).execution;
  const latest = state.commit_adoption?.history?.at(-1);
  if (execution.status !== 'in-review' || !state.git_anchor || !latest
    || latest.commit !== state.git_anchor.head || latest.execution_status !== 'in-review'
    || latest.execution_hash !== state.pm_binding.execution_hash) {
    fail('current finish requires an adopted in-review candidate commit');
  }
}

import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import { readStory } from '../plugins/deliver/skills/deliver/scripts/lib/story.mjs';

const pmCli = fileURLToPath(new URL('../plugins/deliver/skills/deliver/scripts/pm.mjs', import.meta.url));
const runtime = fileURLToPath(new URL('../plugins/deliver/skills/deliver/scripts/deliver.mjs', import.meta.url));
const storyPath = 'docs/stories/S1-1-value.md';
const criterion = 'The value is changed by the bounded implementation.';

function git(root, ...args) {
  return execFileSync('git', ['-C', root, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trimEnd();
}

function write(root, rel, value) {
  const file = path.join(root, ...rel.split('/'));
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, typeof value === 'string' ? value : `${JSON.stringify(value, null, 2)}\n`);
  return file;
}

function story(builder = 'auto') {
  return [
    '# S1-1: Change value',
    `<!-- pm-meta: {"builder":"${builder}","touches":["src"]} -->`,
    'Sprint: 1 · Priority: high · Covers: AC-001 · Depends on: none · Parallel-safe: yes',
    'Risk: low · Review lenses: code-integrity-reviewer · Specs: none',
    '',
    '## Goal',
    'Change the fixture value.',
    '',
    '## Acceptance criteria (testable)',
    `- [ ] ${criterion}`,
    '',
    '## Verification',
    '- Prove done with: `node --test`',
    '',
  ].join('\n');
}

function project(t, { builder = 'auto' } = {}) {
  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'deliver-current-')));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  git(root, 'init', '-q', '--initial-branch=main');
  git(root, 'config', 'user.name', 'Casey Example');
  git(root, 'config', 'user.email', 'casey@example.com');
  const call = (file, ...args) => {
    const result = spawnSync(process.execPath, [file, ...args], { cwd: root, encoding: 'utf8' });
    return { ...result, json: result.stdout ? JSON.parse(result.stdout) : null };
  };
  const pm = (...args) => call(pmCli, ...args);
  const run = (...args) => call(runtime, ...args);
  assert.equal(pm('init').status, 0);
  write(root, 'docs/plan.md', '# Plan\n\n## Delivery mode\n- Scale: standard\n- Checkpoint policy: story-level\n- Integration branch: main\n- Skeleton: none\n');
  write(root, storyPath, story(builder));
  write(root, 'src/value.txt', 'before\n');
  return { root, pm, run };
}

function approve(f) {
  f.gitDigest = git(f.root, 'hash-object', '--', 'docs/plan.md');
  git(f.root, 'add', 'docs', 'src');
  git(f.root, 'commit', '-qm', 'Track pending plan and story');
  const result = f.pm('approve', '--approver', 'Ben');
  assert.equal(result.status, 0, result.stdout);
  assert.equal(result.json.plan_digest, f.gitDigest);
  git(f.root, 'add', 'docs/approval.json');
  git(f.root, 'commit', '-qm', 'Approve shared plan');
}

function packet(root) {
  return write(root, '.deliver/task.json', {
    id: 'S1-1',
    objective: 'Change the fixture value.',
    acceptance: [{ id: 'AC-1', text: criterion }],
    read_paths: [storyPath],
    touches: ['src'],
    commands: {},
    specs: [],
  });
}

test('current lifecycle binds exact approval, claim, route, branch and spent counters', (t) => {
  const f = project(t);
  assert.equal(fs.existsSync(path.join(f.root, 'pm/pm-state.json')), false);
  const downgrade = f.pm('init', '--format', 'legacy');
  assert.notEqual(downgrade.status, 0);
  assert.equal(fs.existsSync(path.join(f.root, 'pm/pm-state.json')), false);
  const pending = JSON.parse(fs.readFileSync(path.join(f.root, 'docs/approval.json'), 'utf8'));
  assert.equal(pending.status, 'pending');
  const beforeUntrackedApproval = fs.readFileSync(path.join(f.root, 'docs/approval.json'), 'utf8');
  const early = f.pm('approve', '--approver', 'Ben');
  assert.notEqual(early.status, 0);
  assert.equal(fs.readFileSync(path.join(f.root, 'docs/approval.json'), 'utf8'), beforeUntrackedApproval);

  approve(f);
  const claim = f.pm('claim', '--story', storyPath);
  assert.equal(claim.status, 0, claim.stdout);
  assert.equal(claim.json.branch, 'pm/S1-1-value');
  let claimedText = fs.readFileSync(path.join(f.root, storyPath), 'utf8');
  claimedText = claimedText.replace('"rounds":0,"retries":0', '"rounds":2,"retries":1');
  fs.writeFileSync(path.join(f.root, storyPath), claimedText);
  git(f.root, 'add', storyPath);
  git(f.root, 'commit', '-qm', 'Publish current story claim');

  const sourceBeforeResume = fs.readFileSync(path.join(f.root, 'src/value.txt'), 'utf8');
  fs.appendFileSync(path.join(f.root, 'src/value.txt'), 'dirty\n');
  const dirtyResume = f.pm('claim', '--story', storyPath);
  assert.notEqual(dirtyResume.status, 0);
  assert.match(dirtyResume.json.error, /clean integration checkout/);
  fs.writeFileSync(path.join(f.root, 'src/value.txt'), sourceBeforeResume);
  const resumed = f.pm('claim', '--story', storyPath);
  assert.equal(resumed.status, 0, resumed.stdout);
  assert.equal(resumed.json.resumed, true);
  assert.equal(resumed.json.rounds, 2);
  assert.equal(resumed.json.retries, 1);
  git(f.root, 'checkout', '-qb', 'pm/S1-1-value');
  const wrongCheckout = f.pm('claim', '--story', storyPath);
  assert.notEqual(wrongCheckout.status, 0);
  assert.match(wrongCheckout.json.error, /integration branch main/);
  packet(f.root);

  const initialized = f.run('init', '--mode', 'quick');
  assert.equal(initialized.status, 0, initialized.stdout);
  assert.equal(initialized.json.plan.path, path.join(f.root, 'docs/plan.md'));
  assert.equal(initialized.json.approval_current, true);
  const runId = initialized.json.run_id;
  const started = f.run('start', '--run', runId, '--task', '.deliver/task.json', '--builder', 'builder', '--story', storyPath);
  assert.equal(started.status, 0, started.stdout);
  assert.deepEqual(started.json.counters, { retries: 1, fixes: 2, corrections: 0 });
  const runState = JSON.parse(fs.readFileSync(path.join(f.root, '.deliver/runs', `${runId}.json`), 'utf8'));
  assert.equal(runState.pm_binding.format, 'current');
  assert.equal(runState.pm_binding.plan_digest, f.gitDigest);
  assert.equal(runState.pm_binding.contract_hash, readStory(f.root, storyPath).contractHash);
  assert.equal(runState.pm_binding.execution_hash, readStory(f.root, storyPath).executionHash);
  assert.equal(runState.pm_binding.actor, readStory(f.root, storyPath).execution.owner);
  assert.equal(runState.pm_binding.builder, 'codex-builder');
  assert.equal(runState.pm_binding.branch, 'pm/S1-1-value');
  assert.equal(runState.pm_binding.integration_branch, 'main');
  assert.equal(f.run('check', '--run', runId).status, 0);

  const runFile = path.join(f.root, '.deliver/runs', `${runId}.json`);
  const boundStateText = fs.readFileSync(runFile, 'utf8');
  fs.writeFileSync(runFile, `${JSON.stringify({ ...runState, pm_binding: null }, null, 2)}\n`);
  write(f.root, '.deliver/unbound-review.json', { status: 'PASS', findings: [] });
  write(f.root, '.deliver/unbound-verification.json', { criteria: [{ id: 'AC-1', status: 'PASS', evidence: 'Fixture evidence.' }] });
  const unboundSnapshot = '0'.repeat(64);
  for (const [command, args] of [
    ['check', []],
    ['gate', ['--name', 'must-not-run', '--command', 'node -e "process.exit(99)"']],
    ['review', ['--snapshot', unboundSnapshot, '--reviewer', 'reviewer', '--receipt', '.deliver/unbound-review.json']],
    ['verify', ['--snapshot', unboundSnapshot, '--verifier', 'verifier', '--results', '.deliver/unbound-verification.json']],
    ['finish', []],
  ]) {
    const denied = f.run(command, '--run', runId, ...args);
    assert.notEqual(denied.status, 0, command);
    assert.match(denied.json.error, /missing its shared story binding/, command);
  }
  assert.equal(JSON.parse(fs.readFileSync(runFile, 'utf8')).revision, runState.revision);
  fs.writeFileSync(runFile, boundStateText);

  const second = f.run('init', '--mode', 'quick');
  assert.equal(second.status, 0, second.stdout);
  const duplicate = f.run('start', '--run', second.json.run_id, '--task', '.deliver/task.json', '--builder', 'second', '--story', storyPath);
  assert.notEqual(duplicate.status, 0);
  assert.match(duplicate.json.error, /already has a current Codex run/);
  assert.equal(readStory(f.root, storyPath).execution.rounds, 2);
  assert.equal(readStory(f.root, storyPath).execution.retries, 1);

  const planBefore = fs.readFileSync(path.join(f.root, 'docs/plan.md'), 'utf8');
  fs.appendFileSync(path.join(f.root, 'docs/plan.md'), '\nchanged\n');
  assert.notEqual(f.run('check', '--run', runId).status, 0);
  fs.writeFileSync(path.join(f.root, 'docs/plan.md'), planBefore);

  const storyBefore = fs.readFileSync(path.join(f.root, storyPath), 'utf8');
  fs.writeFileSync(path.join(f.root, storyPath), storyBefore.replace('"builder":"codex-builder"', '"builder":"expert-builder"'));
  assert.notEqual(f.run('check', '--run', runId).status, 0);
  fs.writeFileSync(path.join(f.root, storyPath), storyBefore);

  git(f.root, 'checkout', 'main');
  assert.notEqual(f.run('check', '--run', runId).status, 0);
  git(f.root, 'checkout', 'pm/S1-1-value');

  const revoked = f.pm('revoke', '--reason', 'The shared plan needs revision.');
  assert.equal(revoked.status, 0, revoked.stdout);
  const marker = JSON.parse(fs.readFileSync(path.join(f.root, 'docs/approval.json'), 'utf8'));
  assert.equal(marker.status, 'revoked');
  assert.equal(marker.reason, 'The shared plan needs revision.');
  assert.equal(marker.plan_digest, f.gitDigest);
  assert.notEqual(f.run('check', '--run', runId).status, 0);
  const gate = f.run('gate', '--run', runId, '--name', 'must-not-run', '--command', 'node -e "process.exit(99)"');
  assert.notEqual(gate.status, 0);
  assert.match(gate.json.error, /approv/);
  write(f.root, '.deliver/review.json', { status: 'PASS', findings: [] });
  write(f.root, '.deliver/verification.json', { criteria: [{ id: 'AC-1', status: 'PASS', evidence: 'Fixture evidence.' }] });
  const staleSnapshot = '0'.repeat(64);
  for (const [command, args] of [
    ['review', ['--snapshot', staleSnapshot, '--reviewer', 'reviewer', '--receipt', '.deliver/review.json']],
    ['verify', ['--snapshot', staleSnapshot, '--verifier', 'verifier', '--results', '.deliver/verification.json']],
    ['finish', []],
  ]) {
    const denied = f.run(command, '--run', runId, ...args);
    assert.notEqual(denied.status, 0, command);
    assert.match(denied.json.error, /approv/, command);
  }
});

